local config = {
  ui_story_5087_50870100_1_dialog_content = "Es una antigua fábula conocida por todos en Northland.",
  ui_story_5087_50870100_2_dialog_content = "Y la primera línea es...",
  ui_story_5087_50870100_3_dialog_content = "\"¿Puedes recordar esas hermosas flores blancas?\"",
  ui_story_5087_50870100_4_dialog_content = "<color=#e8d9bb>Después de recordar la primera frase, los fragmentos de memoria restantes se activan y se elevan uno por uno.</color>",
  ui_story_5087_50870100_5_dialog_content = "<color=#e8d9bb>Un alegre fuego arde en la chimenea, su cálida luz crea sombras danzantes dentro de la pequeña cabaña.</color>",
  ui_story_5087_50870100_6_dialog_content = "<color=#e8d9bb>En el resplandor del fuego, se pueden ver cuatro figuras: un esposo y esposa, así como sus hijas gemelas que parecen imágenes de espejo una de la otra.</color>",
  ui_story_5087_50870100_7_dialog_content = "\"¿Puedes recordar esas hermosas flores blancas? Dos tallos creciendo en armonía junto al tranquilo lago.\"",
  ui_story_5087_50870100_8_dialog_content = "\"Uno era un delicado narciso, el otro un lirio prístino.\"",
  ui_story_5087_50870100_9_dialog_content = "\"Aunque distintos en forma, sus almas eran una.\"",
  ui_story_5087_50870100_10_dialog_content = "\"Uno dio hojas, el otro floreció con flores. Sorbieron el rocío de la mañana, sus raíces entrelazadas para siempre.\"",
  ui_story_5087_50870100_11_dialog_content = "Dado que eran tan unidos, deben haber vivido juntos para siempre, ¿verdad?",
  ui_story_5087_50870100_12_dialog_content = "Desafortunadamente, cada historia debe tener sus giros.",
  ui_story_5087_50870100_13_dialog_content = "\"Bajo la caída de la nieve gris, el lirio prístino pronto fue enterrado.\"",
  ui_story_5087_50870100_14_dialog_content = "\"Dejado solo en el mundo, el narciso blanco lloró en silencio.\"",
  ui_story_5087_50870100_15_dialog_content = "*sollozando* Esa pobre lirio... Debe haber tenido tanto frío bajo toda esa nieve.",
  ui_story_5087_50870100_16_dialog_content = "Siento más lástima por el narciso. ¿No había nadie que pudiera ayudarla?",
  ui_story_5087_50870100_17_dialog_content = "Ambas son niñas tan dulces, como el lirio y el narciso. Northland nunca os dejaría llorar solas.",
  ui_story_5087_50870100_18_dialog_content = "Volvamos a la historia—",
  ui_story_5087_50870100_19_dialog_content = "\"Un día, el Lago Espejo notó las raíces frías y las tristes lágrimas del narciso. Sintiendo lástima por ella, el lago prometió devolver el alma del lirio.\"",
  ui_story_5087_50870100_20_dialog_content = "¿Qué pasó después? ¿Volvió su alma?",
  ui_story_5087_50870100_21_dialog_content = "¿Lograron vivir felices para siempre de nuevo?",
  ui_story_5087_50870100_22_dialog_content = "¡Por supuesto que lo hicieron! ¿Cómo más podría haber terminado la historia?",
  ui_story_5087_50870100_23_dialog_content = "Pero ya pasó su hora de dormir, chicas. Terminemos el cuento mañana, ¿de acuerdo?",
  ui_story_5087_50870100_24_dialog_content = "¡De ninguna manera! ¡Quiero escucharlo ahora!",
  ui_story_5087_50870100_25_dialog_content = "¿Quieres saber si el narciso aún reconoce el alma del lirio, verdad?",
  ui_story_5087_50870100_26_dialog_content = "¡Sí! También quiero saber si vuelven a estar juntos y viven felices para siempre!",
  ui_story_5087_50870100_27_dialog_content = "Por supuesto que sí. Así es como va cada historia, ¿no es así?",
  ui_story_5087_50870100_28_dialog_content = "No importa cuántos giros y vueltas tome la historia...",
  ui_story_5087_50870100_29_dialog_content = "Todos siempre llegan a vivir felices para siempre.",
  ui_story_5087_50870100_30_dialog_content = "Es cierto. Lola una vez dijo que cada historia tiene un final feliz.",
  ui_story_5087_50870100_31_dialog_content = "Pero después de todos estos años, ni siquiera puedo recordar haber escuchado esta historia, mucho menos su final.",
  ui_story_5087_50870100_32_dialog_content = "Una sensación de inquietud me obligó a buscar respuestas, pero todo lo que pude hacer fue tamizar los fragmentos caóticos de mis recuerdos en busca de ellas.",
  ui_story_5087_50870100_33_dialog_content = "Entonces, como si mi deseo hubiera sido concedido, finalmente recordé algo—",
  ui_story_5087_50870100_34_dialog_content = "Una cálida chimenea, una historia contada por una madre y un padre, y dos niñas juguetonas. Todo se sentía tan familiar, y sin embargo tan lejano al mismo tiempo.",
  ui_story_5087_50870100_35_dialog_content = "¿Fue mi pasado? Apenas puedo descifrar quién soy ahora, pero el significado detrás del final de esa historia es claro y definido.",
  ui_story_5087_50870100_36_dialog_content = "Esperé y rogué con todo mi corazón para que ese final se hiciera realidad, incluso si eso significaba... que nunca podría despertar de nuevo.",
  ui_story_5087_50870100_37_dialog_content = "<color=#e8d9bb>\"Desde aquel día, una flor de lirio brotó del narciso, y ambos vivieron felices para siempre...\"</color>",
  ui_story_5087_50870100_38_dialog_content = "Felizmente... para siempre...",
  ui_story_5087_50870100_39_dialog_content = "Eso es correcto, Nikinis. Tú y yo siempre estaremos juntos, y viviremos felices para siempre.",
  ui_story_5087_50870100_40_dialog_content = "... ¿Ah?",
  ui_story_5087_50870100_41_dialog_content = "<color=#e8d9bb>Una fragancia embriagadora flota a través de un campo de flores. El ligero aroma de los narcisos y el rico aroma de los lirios se entremezclan en el aire.</color>",
  ui_story_5087_50870100_42_dialog_content = "<color=#e8d9bb>En la fragancia de las flores, alguien toma de la mano a Nikinis.</color>",
  ui_story_5087_50870100_43_dialog_content = "<color=#e8d9bb>Ella es tan pura y hermosa como un lirio blanco. Aunque difieren en cuerpo y mente, sus espíritus son uno.</color>",
  ui_story_5087_50870100_44_dialog_content = "¿N-Nepolis? ¿Eres realmente tú, hermana?",
  ui_story_5087_50870100_45_dialog_content = "¿Por qué te ves tan sorprendido, Nikinis? No me digas que te enfermaste de nuevo y olvidaste cómo me veo.",
  ui_story_5087_50870100_46_dialog_content = "¡Por supuesto que no! Pero pensé que estabas atrapado en...",
  ui_story_5087_50870100_47_dialog_content = "(... ¿Atrapado en qué? ¿Por qué no puedo recordar?)",
  ui_story_5087_50870100_48_dialog_content = "... Espera, Nepolis, ¡no te vayas! ¡Quédate conmigo!",
  ui_story_5087_50870100_49_dialog_content = "¿Oh? Parece que no estaba imaginando cosas después de todo. Desde que nos recuperamos de nuestra enfermedad, te has vuelto mucho más apegado.",
  ui_story_5087_50870100_50_dialog_content = "Pero no te preocupes, Nikinis. Realmente estoy justo aquí a tu lado.",
  ui_story_5087_50870100_51_dialog_content = "No es una ilusión en un espejo, ni un reflejo en el agua.",
  ui_story_5087_50870100_52_dialog_content = "Tu cara está tan cálida, Nepolis... ¿Realmente estás de vuelta otra vez?",
  ui_story_5087_50870100_53_dialog_content = "(... ¿Por qué dije \"de vuelta otra vez\"?)",
  ui_story_5087_50870100_54_dialog_content = "Siempre que estamos juntos, siento que ni siquiera puedo esconder mis pensamientos de ti.",
  ui_story_5087_50870100_55_dialog_content = "Siempre he podido saber lo que estás pensando, y lo mismo ocurre contigo y mis pensamientos. Ese es nuestro don y nuestra forma de demostrar que siempre nos tendremos el uno al otro.",
  ui_story_5087_50870100_56_dialog_content = "Ahora dame tu mano y camina conmigo. Pronto recordarás las cosas.",
  ui_story_5087_50870100_57_dialog_content = "Como gemelos, compartimos las mismas raíces y tallos. Nacidos con Luminatics muy especiales, nuestros corazones y almas están conectados.",
  ui_story_5087_50870100_58_dialog_content = "Si tengo sed...",
  ui_story_5087_50870100_59_dialog_content = "... Entonces yo también tendré sed.",
  ui_story_5087_50870100_60_dialog_content = "Si decido salir...",
  ui_story_5087_50870100_61_dialog_content = "... Ya tendré nuestros abrigos y botas listos.",
  ui_story_5087_50870100_62_dialog_content = "¡Así es! Nuestro aspecto, nuestros hobbies, nuestros talentos... Tú y yo somos uno y el mismo, Nikinis.",
  ui_story_5087_50870100_63_dialog_content = "Plantamos juntos este campo de flores, entramos juntos al Palacio de Invierno y obtuvimos el honor de servir juntos a Queen Bethlehem.",
  ui_story_5087_50870100_64_dialog_content = "Tú... ¿realmente no recuerdas nada?",
  ui_story_5087_50870100_65_dialog_content = "No... Ahora recuerdo todo. Cuanto más me cuentas sobre nuestro pasado, más recuerdos aparecen en mi mente.",
  ui_story_5087_50870100_66_dialog_content = "Cada vez que sonríes con nostalgia, siento la misma felicidad en mi corazón también.",
  ui_story_5087_50870100_67_dialog_content = "Estar contigo me hace sentir tan... completo, o al menos así es como lo describiría.",
  ui_story_5087_50870100_68_dialog_content = "No puedo imaginar vivir sin ti.",
  ui_story_5087_50870100_69_dialog_content = "Estás hablando de la vez que ambos caímos enfermos, ¿verdad? Ese fue un momento tan aterrador...",
  ui_story_5087_50870100_70_dialog_content = "Me sentí tan débil y apático todos los días. Ni siquiera podía sentir mis propias extremidades, mucho menos a ti.",
  ui_story_5087_50870100_71_dialog_content = "Creo que esa fue la primera vez que perdimos nuestra conexión el uno con el otro.",
  ui_story_5087_50870100_72_dialog_content = "Es cierto... También me enfermé, por eso mis recuerdos y sentimientos se han vuelto tan confusos.",
  ui_story_5087_50870100_73_dialog_content = "Jeje... Entonces todavía somos los mismos que cuando éramos niños, compartiendo cada momento de dolor y tristeza.",
  ui_story_5087_50870100_74_dialog_content = "Para ser honesto, es un poco incómodo. Cuando uno de nosotros se enfermaba, el otro seguía su ejemplo... ¡Nuestros padres deben haber estado muy preocupados!",
  ui_story_5087_50870100_75_dialog_content = "Nuestros padres... ¡Es cierto! ¿Están bien? ¿Puedo ir a casa y verlos?",
  ui_story_5087_50870100_76_dialog_content = "Por supuesto. Pero antes de que nos vayamos a casa, tenemos que terminar nuestra misión.",
  ui_story_5087_50870100_77_dialog_content = "¿Nuestra misión?",
  ui_story_5087_50870100_78_dialog_content = "¿Qué, olvidaste toda la misión de Su Majestad después de una pequeña siesta?",
  ui_story_5087_50870100_79_dialog_content = "La reina nos ordenó recuperar un artefacto perdido del bosque.",
  ui_story_5087_50870201_1_dialog_content = "No tenemos mucho tiempo, así que hagamos las cosas de la manera habitual. ¡Despejaremos la nieve a medida que avancemos!",
  ui_story_5087_50870201_2_dialog_content = "¡De acuerdo!",
  ui_story_5087_50870201_3_dialog_content = "Nuestra misión es... ¿recuperar un artefacto perdido para Queen Bethlehem?",
  ui_story_5087_50870201_4_dialog_content = "Sí. Una reliquia fue robada de la bóveda de tesoros del Palacio de Invierno. Es un objeto peligroso que puede perturbar el espíritu mismo de una persona.",
  ui_story_5087_50870201_5_dialog_content = "La reina teme que cause un sufrimiento incontable si cae en manos de la gente, por lo que envió a muchos de sus leales sirvientes a buscarlo.",
  ui_story_5087_50870201_6_dialog_content = "¿Robado? ¿Qué tipo de ladrón sería lo suficientemente tonto como para hacer algo así?",
  ui_story_5087_50870201_7_dialog_content = "Jeje, creo que una mejor pregunta sería ¿qué tipo de reina sería tan misericordiosa al respecto?",
  ui_story_5087_50870201_8_dialog_content = "Una reliquia inestimable es robada de su palacio, y su primera preocupación es recuperarla antes de que pueda amenazar la seguridad de su pueblo. Para Su Majestad, la captura del ladrón tiene mucha menos prioridad.",
  ui_story_5087_50870201_9_dialog_content = "La reina siempre ha sido así.",
  ui_story_5087_50870201_10_dialog_content = "No puedo contar la cantidad de historias que he escuchado sobre Su Majestad resolviendo todo tipo de problemas para su pueblo.",
  ui_story_5087_50870201_11_dialog_content = "Incluso si fuera algo tan trivial como rescatar ganado del bosque o despejar la nieve de las carreteras de montaña...",
  ui_story_5087_50870201_12_dialog_content = "Al menos no tenemos que preocuparnos por la nieve, ¿verdad? ¿Ves lo bien que trabajamos juntos? ¡Oye, este lado es mío!",
  ui_story_5087_50870201_13_dialog_content = "La reina nos ha cuidado durante tanto tiempo como puedo recordar...",
  ui_story_5087_50870201_14_dialog_content = "Incluso curó mi enfermedad.",
  ui_story_5087_50870201_15_dialog_content = "Por eso elegiste quedarte en el Palacio de Invierno y servirla.",
  ui_story_5087_50870201_16_dialog_content = "Estoy seguro de que ella también curó tu enfermedad.",
  ui_story_5087_50870201_17_dialog_content = "Mientras te sientas mejor, yo también. No hay necesidad de molestar a la reina por eso.",
  ui_story_5087_50870201_18_dialog_content = "¡Uno más! Uf, finalmente lo logramos.",
  ui_story_5087_50870201_19_dialog_content = "Alguien informó haber visto el artefacto robado cerca de esa cabaña más adelante.",
  ui_story_5087_50870201_20_dialog_content = "Hola, ¿hay alguien en casa? Fuimos enviados por el Palacio de Invierno.",
  ui_story_5087_50870201_21_dialog_content = "<color=#e8d9bb>El interior de la cabaña está mortalmente silencioso.</color>",
  ui_story_5087_50870201_22_dialog_content = "(Sin respuesta... ¿Eh? Pisé algo brillante... ¿un fragmento roto de algún tipo?)",
  ui_story_5087_50870201_23_dialog_content = "¿Qué es, Nikinis?",
  ui_story_5087_50870201_24_dialog_content = "Ten cuidado, Nepolis. Yo tengo...",
  ui_story_5087_50870201_25_dialog_content = "... Un mal presentimiento sobre esto.",
  ui_story_5087_50870201_26_dialog_content = "<color=#e8d9bb>Las gemelas colocan una mano en la puerta cada una. De pie a ambos lados de ella, la empujan cuidadosamente para abrirla.</color>",
  ui_story_5087_50870201_27_dialog_content = "!",
  ui_story_5087_50870201_28_dialog_content = "¿Es eso... un espejo?",
  ui_story_5087_50870201_29_dialog_content = "Está completamente roto...",
  ui_story_5087_50870201_30_dialog_content = "(¿Qué está pasando? Por alguna razón, este espejo me resulta tan familiar...)",
  ui_story_5087_50870201_31_dialog_content = "(¿Eh? ¿Acabo de ver a una persona en el espejo?)",
  ui_story_5087_50870201_32_dialog_content = "Nikinis... Nikinis...",
  ui_story_5087_50870201_33_dialog_content = "¿Quién eres tú? ¿Por qué me estás llamando? Y... ¿qué estás haciendo en este espejo?",
  ui_story_5087_50870201_34_dialog_content = "Nikinis... No...",
  ui_story_5087_50870201_35_dialog_content = "No puedo oírte.",
  ui_story_5087_50870201_36_dialog_content = "¡Deténgase! ¡No des un paso más!",
  ui_story_5087_50870201_37_dialog_content = "!",
  ui_story_5087_50870201_38_dialog_content = "¡Esa es la reliquia robada del Palacio de Invierno, Nikinis!",
  ui_story_5087_50870201_39_dialog_content = "Se llama el Espejo de Northland, ¡y es uno de los objetos más peligrosos en la colección de la reina!",
  ui_story_5087_50870201_40_dialog_content = "¿Qué es eso?",
  ui_story_5087_50870201_41_dialog_content = "(Entonces, ¿por qué alguien dentro de este peligroso artefacto me llamaría?)",
  ui_story_5087_50870201_42_dialog_content = "¡Cuidado, Nikinis!",
  ui_story_5087_50870201_43_dialog_content = "<color=#e8d9bb>Sobresaltado, Nikinis solo logra ver cómo los fragmentos dispersos del espejo comienzan a temblar.</color>",
  ui_story_5087_50870201_44_dialog_content = "<color=#e8d9bb>De repente, innumerables rayos de oscuridad estallan de los fragmentos y convergen.</color>",
  ui_story_5087_50870201_45_dialog_content = "<color=#e8d9bb>Una presencia indistinta, no diferente a una sombra.</color>",
  ui_story_5087_50870201_46_dialog_content = "¡Mantente alejado de mi hermana!",
  ui_story_5087_50870202_1_dialog_content = "¡Nepolis! ¿Estás herido? Puedo sentir tu dolor—",
  ui_story_5087_50870202_2_dialog_content = "Este no es el momento de mantener nuestra conexión, tonto. Si compartes mi dolor, ambas vidas estarán en peligro en las batallas.",
  ui_story_5087_50870202_3_dialog_content = "Lo siento... Pero te lastimaste por mi culpa...",
  ui_story_5087_50870202_4_dialog_content = "No se pudo evitar. Después de todo, tú habrías hecho lo mismo por mí, ¿verdad?",
  ui_story_5087_50870202_5_dialog_content = "¿Qué te pasó justo ahora? No es propio de ti acercarte a ese espejo mágico tan imprudentemente.",
  ui_story_5087_50870202_6_dialog_content = "Estoy teniendo dificultades para entender tus emociones en este momento...",
  ui_story_5087_50870202_7_dialog_content = "Es solo que... Vi a alguien moverse en el espejo, así que quería mirar más de cerca.",
  ui_story_5087_50870202_8_dialog_content = "¿Viste a alguien? ¿Estás seguro de que no eran solo nuestros reflejos?",
  ui_story_5087_50870202_9_dialog_content = "Yo... no creo? Déjame ir a echar otro vistazo-",
  ui_story_5087_50870202_10_dialog_content = "No creo que sea una buena idea. Ese espejo es demasiado peligroso, y no hay forma de saber qué podría pasarnos si nos acercamos a él.",
  ui_story_5087_50870202_11_dialog_content = "Usaremos nuestra Luminatics para empaquetarlo y transportarlo de vuelta al Palacio de Invierno.",
  ui_story_5087_50870202_12_dialog_content = "... Tienes razón, Nepolis. Comencemos.",
  ui_story_5087_50870202_13_dialog_content = "<color=#e8d9bb>Las dos hermanas activan sus Luminatics simultáneamente. Ramas verdes crecen del suelo a ambos lados del espejo y florecen con flores blancas.</color>",
  ui_story_5087_50870202_14_dialog_content = "<color=#e8d9bb>Pronto, la cabaña entera se llena con el olor de las flores. A medida que las ramas en flor trepan por las paredes de la cabaña, el espejo roto se envuelve apretadamente.</color>",
  ui_story_5087_50870202_15_dialog_content = "¡Urgh! Hay algo en el espejo... ¡y está intentando salir!",
  ui_story_5087_50870202_16_dialog_content = "¡Solo espera! ¡Ya voy!",
  ui_story_5087_50870202_17_dialog_content = "Phew...",
  ui_story_5087_50870202_18_dialog_content = "Jeje, parece que lo logramos, ¿eh? ¡No esperaba menos de nosotras, las hermanas!",
  ui_story_5087_50870202_19_dialog_content = "Te mereces todo el crédito, Nepolis... Ha pasado tanto tiempo desde mi última pelea que olvidé tomar precauciones.",
  ui_story_5087_50870202_20_dialog_content = "No creo que pudiera haber manejado esto sin ti...",
  ui_story_5087_50870202_21_dialog_content = "¡Para nada! Puedo decir lo poderoso que eres solo con mirar estas flores.",
  ui_story_5087_50870202_22_dialog_content = "¿Ves? ¡Solo mira lo bien que están floreciendo!",
  ui_story_5087_50870202_23_dialog_content = "<color=#e8d9bb>Por el poder de sus Luminatics, la cabaña está enterrada bajo un mar de flores blancas puras.</color>",
  ui_story_5087_50870202_24_dialog_content = "<color=#e8d9bb>Narcisos delicados y lirios prístinos, nacidos uno al lado del otro.</color>",
  ui_story_5087_50870202_25_dialog_content = "Nuestras flores floreciendo juntas... Por alguna razón, siento que hace mucho tiempo que no veo algo así...",
  ui_story_5087_50870202_26_dialog_content = "\"¿Puedes recordar esas hermosas flores blancas?\"",
  ui_story_5087_50870202_27_dialog_content = "Las flores de Nepolis... Ah.",
  ui_story_5087_50870202_28_dialog_content = "Estoy aquí, ¿recuerdas? No tienes que seguir mirando mis flores, ya sabes.",
  ui_story_5087_50870202_29_dialog_content = "¡Una vez que regresemos del Palacio de Invierno, podemos volver al Lago Espejo y cuidar nuestro campo de flores!",
  ui_story_5087_50870300_1_dialog_content = "<color=#e8d9bb>El Palacio de Invierno es el asiento de la autoridad real en Northland y un lugar considerado sagrado por los norteños desde hace mucho tiempo.</color>",
  ui_story_5087_50870300_2_dialog_content = "¡Increíble... Ustedes dos en realidad lograron recuperar el Espejo de Northland! Apenas puedo creerlo!",
  ui_story_5087_50870300_3_dialog_content = "Todo fue gracias a mi hermana...",
  ui_story_5087_50870300_4_dialog_content = "No seas tan modesto, Nikinis! Mira, incluso nos sirvieron algo del té más preciado de Su Majestad.",
  ui_story_5087_50870300_5_dialog_content = "Este material no es barato, ¿sabes? La última vez que quería una taza, les rogué durante tres días seguidos, pero aún así me rechazaron.",
  ui_story_5087_50870300_6_dialog_content = "¡Jajaja, bueno... Como sabes, el robo del Espejo del Norte fue un asunto bastante grave!",
  ui_story_5087_50870300_7_dialog_content = "Dicen que esta reliquia es incluso más antigua que el Palacio de Invierno y ocupa un lugar muy único dentro de la colección de la reina.",
  ui_story_5087_50870300_8_dialog_content = "Para que desaparezca en medio de la noche sin dejar rastro... ¡el pobre Maestro Novio apenas ha dormido desde entonces!",
  ui_story_5087_50870300_9_dialog_content = "¡Ahora que está de nuevo en nuestra posesión, la realeza puede ahorrarse aún más noches en vela... al menos por ahora! ¡Jajaja!",
  ui_story_5087_50870300_10_dialog_content = "Nos sentimos honrados de ayudar al Maestro Novio con algo tan importante. Desafortunadamente, no hemos encontrado ninguna pista sobre el ladrón...",
  ui_story_5087_50870300_11_dialog_content = "...",
  ui_story_5087_50870300_12_dialog_content = "¿Hmm? ¿Qué pasa, Nikinis? Pareces inquieto... ¿Estás nervioso por estar en el gran Palacio de Invierno?",
  ui_story_5087_50870300_13_dialog_content = "Honestamente, desearía que no me molestaras tanto a veces.",
  ui_story_5087_50870300_14_dialog_content = "Es solo que... El Palacio de Invierno parece un poco diferente hoy.",
  ui_story_5087_50870300_15_dialog_content = "¿Qué tiene de diferente?",
  ui_story_5087_50870300_16_dialog_content = "(No estoy seguro... ¿Por qué es tan difícil recordar cómo era el Palacio de Invierno antes?)",
  ui_story_5087_50870300_17_dialog_content = "No puedo precisar exactamente qué es... ¿Quizás simplemente se ve especialmente limpio hoy? Es tan brillante y claro que parece que falta algo...",
  ui_story_5087_50870300_18_dialog_content = "Y aquí pensaba que todo en ti era sobre la limpieza.",
  ui_story_5087_50870300_19_dialog_content = "¡Su Majestad!",
  ui_story_5087_50870300_20_dialog_content = "¡S-Su Majestad! Por favor, perdónanos si nuestras discusiones te ofendieron...",
  ui_story_5087_50870300_21_dialog_content = "No había nada de qué ofenderse, Nikinis. De hecho, estoy de acuerdo contigo. Cuando un espacio está demasiado limpio, puede ser algo inquietante.",
  ui_story_5087_50870300_22_dialog_content = "Un palacio debería tener más signos de vida, como humo de vela y hojas de té desechadas. Quizás pueda pedirle a Noah y a los demás que me ayuden con esto.",
  ui_story_5087_50870300_23_dialog_content = "E-Eso no es lo que quise decir, Su Majestad...",
  ui_story_5087_50870300_24_dialog_content = "Creo que la reina nos está diciendo que deberíamos visitar más a menudo, hermana.",
  ui_story_5087_50870300_25_dialog_content = "Si asistimos al club de lectura de Su Majestad y a las sesiones de té de la tarde, ¡añadiremos más \"signos de vida\" al palacio!",
  ui_story_5087_50870300_26_dialog_content = "¡Cuidado, Nepolis! No te quemes tan mal por algo como el té...",
  ui_story_5087_50870300_27_dialog_content = "Jeje... Mi hermana puede ser tan adorable a veces. ¿No estás de acuerdo, Su Majestad?",
  ui_story_5087_50870300_28_dialog_content = "¡Nepolis!",
  ui_story_5087_50870300_29_dialog_content = "Como hermanas, las dos no podrían estar más unidas. Su vínculo les otorga a ambas fuerza y unidad, y esa es la razón por la que pudieron recuperar el Espejo de Northland.",
  ui_story_5087_50870300_30_dialog_content = "Su trabajo es muy apreciado, Nepolis y Nikinis.",
  ui_story_5087_50870300_31_dialog_content = "Solo estábamos haciendo nuestro deber para mantener a Northland segura.",
  ui_story_5087_50870300_32_dialog_content = "Su Majestad, ¿puedo preguntar... qué pasó con ese espejo?",
  ui_story_5087_50870300_33_dialog_content = "El Espejo de Northland puede convertir lo que refleja en poder, que luego se transforma en monstruos hechos de sombras.",
  ui_story_5087_50870300_34_dialog_content = "He sellado tanto el espejo como el monstruo que habita en él. No representa ninguna amenaza por el momento.",
  ui_story_5087_50870300_35_dialog_content = "Aún tenemos mucho que investigar con respecto a su robo. Dime, ¿notaste algo inusual en el lugar donde lo encontraste?",
  ui_story_5087_50870300_36_dialog_content = "... En verdad, todo acerca de la escena era inusual.",
  ui_story_5087_50870300_37_dialog_content = "No había nadie más en la cabaña donde estaba escondido el espejo, ni tampoco había señales del ladrón...",
  ui_story_5087_50870300_38_dialog_content = "Cuando entramos a la cabaña, el espejo ya había sido destrozado. No había pistas sobre quién lo destrozó o por qué lo hizo...",
  ui_story_5087_50870300_39_dialog_content = "El suelo estaba lleno de fragmentos rotos del espejo, y pronto varias haces de oscuridad escaparon de ellos. Eran muy parecidos a los monstruos sombríos que acabas de describir, Su Majestad...",
  ui_story_5087_50870300_40_dialog_content = "Nikinis dijo que también vio una figura misteriosa en el espejo.",
  ui_story_5087_50870300_41_dialog_content = "...",
  ui_story_5087_50870300_42_dialog_content = "Monstruos sombríos y una figura misteriosa... temo que todos estos son productos del poder del Espejo de Northland.",
  ui_story_5087_50870300_43_dialog_content = "Es probable que el ladrón activara accidentalmente el espejo al quedar atrapado en su reflejo.",
  ui_story_5087_50870300_44_dialog_content = "Si lo que dijiste es cierto, sellar el espejo en sí mismo no será suficiente para garantizar la seguridad del reino.",
  ui_story_5087_50870300_45_dialog_content = "Temo que los fragmentos del espejo también contengan partes del poder de esos monstruos. Por la seguridad de nuestra gente, todos deben ser recuperados.",
  ui_story_5087_50870300_46_dialog_content = "May ¿También les confío a los dos esta misión?",
  ui_story_5087_50870300_47_dialog_content = "¡Por supuesto, Su Majestad! Estamos agradecidos por cualquier oportunidad de servirle.",
  ui_story_5087_50870300_48_dialog_content = "Su Majestad... May ¿Puedo hacerle una pregunta?",
  ui_story_5087_50870300_49_dialog_content = "Por todos los medios.",
  ui_story_5087_50870300_50_dialog_content = "Algo acerca de ese espejo se sentía increíblemente familiar, como si nos hubiéramos visto hace mucho tiempo...",
  ui_story_5087_50870300_51_dialog_content = "¿Podrías explicar por qué me sentí así?",
  ui_story_5087_50870300_52_dialog_content = "¿En serio? Eso es extraño. No sentí nada de eso en absoluto.",
  ui_story_5087_50870300_53_dialog_content = "... Parece que no tiene sentido ocultártelo, Nikinis.",
  ui_story_5087_50870300_54_dialog_content = "Tu intuición es completamente correcta. Ya te has encontrado con el Espejo de Northland una vez antes.",
  ui_story_5087_50870300_55_dialog_content = "¡Lo sabía!",
  ui_story_5087_50870300_56_dialog_content = "Sucedió cuando los dos se enfermaron.",
  ui_story_5087_50870300_57_dialog_content = "En aquel momento, Nepolis estaba asediada por una terrible fiebre, pero tú estabas perfectamente sano. Sin embargo, con el tiempo, comenzaste a mostrar síntomas similares.",
  ui_story_5087_50870300_58_dialog_content = "Los dos siempre han sido así. Vuestra conexión de cuerpo y alma os hace dos veces más poderosos, pero también dos veces más vulnerables.",
  ui_story_5087_50870300_59_dialog_content = "Tus padres buscaron desesperadamente la ayuda de varios médicos, pero todo fue en vano. Finalmente, no tuvieron más opción que llevarte al palacio y pedir mi asistencia.",
  ui_story_5087_50870300_60_dialog_content = "Para prevenir cualquier interrupción en tu recuperación, mi primera opción de acción fue cortar temporalmente tu conexión.",
  ui_story_5087_50870300_61_dialog_content = "Para ese fin, necesitaba una reliquia poderosa capaz de influir en las almas de los seres vivos—",
  ui_story_5087_50870300_62_dialog_content = "¡El Espejo de Northland!",
  ui_story_5087_50870300_63_dialog_content = "Precisamente. En aquel momento, mostraste una afinidad extremadamente alta por el Espejo de Northland.",
  ui_story_5087_50870300_64_dialog_content = "Es por eso también que pude separarlos exitosamente a los dos y curar sus enfermedades.",
  ui_story_5087_50870300_65_dialog_content = "...",
  ui_story_5087_50870300_66_dialog_content = "Entiendo... Creo que recuerdo vagamente que nuestros padres nos llevaron al Palacio de Invierno para tratamiento...",
  ui_story_5087_50870300_67_dialog_content = "¡Por eso se sentía tan familiar! Le debo mi vida a ese espejo...",
  ui_story_5087_50870300_68_dialog_content = "... Esa es la verdad del asunto. Y ahora que lo recuerdas, no tengo razón para negarlo.",
  ui_story_5087_50870300_69_dialog_content = "Pero hay una cosa que siempre debes recordar: nunca te acerques al espejo y nunca creas las palabras pronunciadas por sus reflejos.",
  ui_story_5087_50870300_70_dialog_content = "Como una de las reliquias más antiguas y poderosas de Northland, está rodeada de peligro y misterio en medidas igualmente altas.",
  ui_story_5087_50870300_71_dialog_content = "Incluso las antiguas civilizaciones, que eran capaces de crear maravillas como el Faro y los Colosos—",
  ui_story_5087_50870300_72_dialog_content = "Estaban a eones de comprender completamente el poder del espejo.",
  ui_story_5087_50870400_1_dialog_content = "¡Fuera, monstruos!",
  ui_story_5087_50870400_2_dialog_content = "Graaah...",
  ui_story_5087_50870400_3_dialog_content = "¡No está mal! A este ritmo, encontraremos el resto de los fragmentos del espejo en poco tiempo, y nuestra misión estará completa.",
  ui_story_5087_50870400_4_dialog_content = "... Y todo es gracias a tu habilidad para sentir la presencia del espejo.",
  ui_story_5087_50870400_5_dialog_content = "¡Solo me alegro de poder ser útil finalmente, Nepolis! De hecho, déjame ir a ver si hay más fragmentos cerca.",
  ui_story_5087_50870400_6_dialog_content = "... Claro. Cuento contigo.",
  ui_story_5087_50870400_7_dialog_content = "¿Eh? ¿Qué pasa, Nepolis? Pareces un poco triste.",
  ui_story_5087_50870400_8_dialog_content = "¡N-En absoluto! Si acaso, tú eres el que está actuando diferente! ¿Qué te pasa?",
  ui_story_5087_50870400_9_dialog_content = "Supongo que no hay forma de ocultártelo.",
  ui_story_5087_50870400_10_dialog_content = "¿Recuerdas lo que Queen Bethlehem nos contó sobre el Espejo del Norte?",
  ui_story_5087_50870400_11_dialog_content = "Por supuesto. Ella dijo que los poderes del espejo no se limitan solo a crear monstruos...",
  ui_story_5087_50870400_12_dialog_content = "Puede usar cualquier cosa atrapada en su reflejo para crear ilusiones realistas, que luego pueden influir en las personas hasta en sus mismas almas.",
  ui_story_5087_50870400_13_dialog_content = "Debido a que fue creado por una civilización desconocida hace siglos, el espejo contiene un poder abrumador y primordial...",
  ui_story_5087_50870400_14_dialog_content = "Ni la reina ni las civilizaciones de antes de nuestro tiempo pudieron comprenderlo completamente...",
  ui_story_5087_50870400_15_dialog_content = "Incluso las organizaciones más heréticas de Northland, las que son expertas en reliquias antiguas como esta, están totalmente desconcertadas por su magia.",
  ui_story_5087_50870400_16_dialog_content = "Para desbloquear el potencial completo de una reliquia tan poderosa, se requiere un anfitrión adecuado como su recipiente...",
  ui_story_5087_50870400_17_dialog_content = "Pero convertirse en su huésped ofrece una posibilidad mucho mayor de morir antes de obtener su poder.",
  ui_story_5087_50870400_18_dialog_content = "Nepolis... A pesar de lo peligroso que puede ser este espejo, Queen Bethlehem corrió el riesgo de usarlo para salvarnos...",
  ui_story_5087_50870400_19_dialog_content = "Ahora que conocemos la verdad, es nuestro turno de pagarle... Pero hasta ahora, todo lo que he hecho es confiar en tu fuerza.",
  ui_story_5087_50870400_20_dialog_content = "Con mi habilidad para sentir la presencia del espejo, finalmente puedo ayudarte—",
  ui_story_5087_50870400_21_dialog_content = "... ¡Detente!",
  ui_story_5087_50870400_22_dialog_content = "¿N-Nepolis?",
  ui_story_5087_50870400_23_dialog_content = "No podemos confiar demasiado en tu afinidad con el espejo, ni dejar que tu alma se acerque demasiado a él.",
  ui_story_5087_50870400_24_dialog_content = "\"Quienquiera que sea elegido por el espejo para convertirse en su anfitrión tiene una mayor probabilidad de morir antes de obtener su poder\". ¿Ya has olvidado lo que nos dijo la reina?",
  ui_story_5087_50870400_25_dialog_content = "Necesitamos apresurarnos y recoger los fragmentos restantes, y luego no se te permite acercarte a él nunca más.",
  ui_story_5087_50870400_26_dialog_content = "Después de que nuestra misión termine, finalmente podemos volver a casa a nuestro campo de flores. Estaremos a salvo, y nuestros corazones y mentes volverán a ser uno...",
  ui_story_5087_50870400_27_dialog_content = "¡P-Por supuesto! Prometo que no me acercaré precipitadamente al espejo nunca más.",
  ui_story_5087_50870400_28_dialog_content = "... Y si tenemos que acercarnos a él, déjame ir en tu lugar. Después de todo, no tengo afinidad con él.",
  ui_story_5087_50870400_29_dialog_content = "Cada vez que hablamos del espejo, siento que te alejas más de mí...",
  ui_story_5087_50870400_30_dialog_content = "Graah!",
  ui_story_5087_50870400_31_dialog_content = "¡Nepolis! ¡Los monstruos del espejo también vienen de aquí!",
  ui_story_5087_50870400_32_dialog_content = "¡Muévete, Nikinis!",
  ui_story_5087_50870400_33_dialog_content = "¡Déjame el bosque a mí! ... ¿Eh? ¿Por qué ese se ve diferente al resto?",
  ui_story_5087_50870400_34_dialog_content = "¡Espera ahí mismo, monstruo!",
  ui_story_5087_50870400_35_dialog_content = "¿A dónde fue?",
  ui_story_5087_50870400_36_dialog_content = "(Eso no era una ilusión hace un momento. Parecía que estaba hecho de cristales de hielo... ¿Podría ser también obra del Espejo de Northland?)",
  ui_story_5087_50870400_37_dialog_content = "<color=#e8d9bb>De repente, se puede escuchar un susurro desde lo más profundo del bosque.</color>",
  ui_story_5087_50870400_38_dialog_content = "(... ¡Está viniendo!)",
  ui_story_5087_50870400_39_dialog_content = "...",
  ui_story_5087_50870400_40_dialog_content = "¿Una niña?",
  ui_story_5087_50870501_1_dialog_content = "Buenas tardes.",
  ui_story_5087_50870501_2_dialog_content = "(Este niño parece totalmente tranquilo...)",
  ui_story_5087_50870501_3_dialog_content = "¿Qué estás haciendo sola en el bosque, pequeña niña? ¿Está tu casa cerca?",
  ui_story_5087_50870501_4_dialog_content = "Estoy... vendiendo cosas.",
  ui_story_5087_50870501_5_dialog_content = "Oh, sí, estás llevando una cesta de flores. ¿Es eso lo que estás vendiendo?",
  ui_story_5087_50870501_6_dialog_content = "Tengo otros artículos a la venta también, pero aún no he realizado ninguna transacción. Por lo tanto, no estoy listo para irme a casa.",
  ui_story_5087_50870501_7_dialog_content = "\"¿\"Así que\"? Jeje, para alguien tan joven, seguro que sabes hablar como un adulto. ¡Estoy impresionado!",
  ui_story_5087_50870501_8_dialog_content = "¡A-Aprendí eso de mi mamá y papá!",
  ui_story_5087_50870501_9_dialog_content = "No te preocupes, no soy una mala persona. El bosque puede ser un lugar peligroso, ¿sabes? Incluso hay un monstruo suelto en este momento.",
  ui_story_5087_50870501_10_dialog_content = "¿Sabes cómo llegar a casa? Puedo acompañarte de regreso, si quieres.",
  ui_story_5087_50870501_11_dialog_content = "No tengo miedo de los monstruos.",
  ui_story_5087_50870501_12_dialog_content = "¿E-Eso es así? Creo que al menos deberías tenerles un poco de miedo...",
  ui_story_5087_50870501_13_dialog_content = "Lo único que temo es no poder ayudar a mi familia con su carga. Entonces, ¿podrías ayudarme comprando algo, señorita?",
  ui_story_5087_50870501_14_dialog_content = "Como este espejo de mano, por ejemplo. ¿No es simplemente encantador?",
  ui_story_5087_50870501_15_dialog_content = "!",
  ui_story_5087_50870501_16_dialog_content = "(Espera, creo que es solo un espejo ordinario. Gracias a Dios... Aún así, no creo que a Nepolis le gustaría si volviera con un espejo.)",
  ui_story_5087_50870501_17_dialog_content = "Lo siento, querido, pero últimamente he tenido mucha mala suerte con los espejos.",
  ui_story_5087_50870501_18_dialog_content = "... Multa.",
  ui_story_5087_50870501_19_dialog_content = "Entonces... ¿Qué tal algunas flores recién cortadas? ¿Estarías dispuesto a comprar algunas?",
  ui_story_5087_50870501_20_dialog_content = "¿Ves? Tengo rosas amarillas, no-me-olvides e incluso algunos narcisos blancos! Uno de estos debe llamar tu atención, ¿verdad?",
  ui_story_5087_50870501_21_dialog_content = "¡Qué casualidad! Resulta que amo todas estas flores más que ninguna!",
  ui_story_5087_50870501_22_dialog_content = "Me alegra escuchar eso, señorita.",
  ui_story_5087_50870501_23_dialog_content = "Entonces debes saber lo que ellos <color=#FFB400>simbolizan</color>, ¿sí?",
  ui_story_5087_50870501_24_dialog_content = "Lo que simbolizan...",
  ui_story_5087_50870501_25_dialog_content = "¿Más flores? Qué amable de tu parte, Nikinis. Ahora bien, ¿qué me has traído hoy? ¿Rosas amarillas y no-me-olvides?",
  ui_story_5087_50870501_26_dialog_content = "Sí, Su Majestad. Siempre he querido presentarle estas flores por lo que simbolizan—",
  ui_story_5087_50870501_27_dialog_content = "(Ese recuerdo que vi en mi mente justo ahora... ¿Cuándo ocurrió eso?)",
  ui_story_5087_50870501_28_dialog_content = "(Cuando miro a esta pequeña niña... ¿por qué de repente recuerdo a la reina?)",
  ui_story_5087_50870501_29_dialog_content = "... ¡Nikinis! ¡Cuidado!",
  ui_story_5087_50870501_30_dialog_content = "¡Graaah!",
  ui_story_5087_50870501_31_dialog_content = "¡Ponte detrás de mí, niñita!",
  ui_story_5087_50870501_32_dialog_content = "Me temo que no puedo hacer eso.",
  ui_story_5087_50870501_33_dialog_content = "No importa dónde esté, debo ayudar a mi familia con su carga.",
  ui_story_5087_50870502_1_dialog_content = "¿Puedes usar Luminatics?",
  ui_story_5087_50870502_2_dialog_content = "Y hábilmente, a eso...",
  ui_story_5087_50870502_3_dialog_content = "Esto es apenas inusual aquí en Northland.",
  ui_story_5087_50870502_4_dialog_content = "Estabas tratando de protegerme justo ahora, ¿verdad? Gracias, por favor acepta estas flores como muestra de mi gratitud. ¡Adiós!",
  ui_story_5087_50870502_5_dialog_content = "¡Espera, vuelve! No puedo simplemente tomar estos gratis... ¡Al menos dime tu nombre!",
  ui_story_5087_50870502_6_dialog_content = "Shaya. Mi nombre es Shaya.",
  ui_story_5087_50870502_7_dialog_content = "Nikinis—",
  ui_story_5087_50870502_8_dialog_content = "¿Estás bien? Ese monstruo no te lastimó, ¿verdad? ¿Y con quién estabas hablando justo ahora?",
  ui_story_5087_50870502_9_dialog_content = "Estoy bien, Nepolis. Conocí a una pequeña niña vendiendo flores en el bosque, y ella me dio un ramo por ayudarla. ¿Ves?",
  ui_story_5087_50870502_10_dialog_content = "Eso es genial ya que todas son tus flores favoritas.",
  ui_story_5087_50870502_11_dialog_content = "Nunca te han gustado las multitudes, y siempre te escabullías del Palacio de Invierno durante los banquetes, incluso los que eran para ti...",
  ui_story_5087_50870502_12_dialog_content = "¡Pero cada vez, las personas a las que ayudaste te encontrarían y te darían flores! Hermosos ramos de narcisos blancos y lirios.",
  ui_story_5087_50870502_13_dialog_content = "Estoy seguro de que esa niña también era... ¿Eh?",
  ui_story_5087_50870502_14_dialog_content = "Este ramo solo tiene narcisos blancos en él...",
  ui_story_5087_50870502_15_dialog_content = "!",
  ui_story_5087_50870502_16_dialog_content = "Vamos, Nikinis. Asegurémonos de que no hay más fragmentos de espejo por aquí antes de informar al Palacio de Invierno.",
  ui_story_5087_50870502_17_dialog_content = "(¿Está Nepolis... enfurruñada? Eso es extraño, no creo haber visto nunca este lado de ella.)",
  ui_story_5087_50870502_18_dialog_content = "(Solo pondré una de estas flores en su cabello. De esa manera, el narciso blanco y el lirio estarán juntos de nuevo.)",
  ui_story_5087_50870502_19_dialog_content = "¿Mmm? Hay algo duro escondido dentro de este ramo...",
  ui_story_5087_50870502_20_dialog_content = "¡Es ese espejo de mano!",
  ui_story_5087_50870502_21_dialog_content = "(¿Hizo Shaya esto a propósito? ¿Metió este espejo en el ramo porque me negué a comprarlo?)",
  ui_story_5087_50870502_22_dialog_content = "(¿Por qué estaba tan decidida a darme esto?)",
  ui_story_5087_50870502_23_dialog_content = "Nikinis... Nikinis...",
  ui_story_5087_50870502_24_dialog_content = "(¡Es él de nuevo! ¡La voz del Espejo de Northland! ¿También puede aparecer en otros espejos?)",
  ui_story_5087_50870502_25_dialog_content = "(Esto es malo, le prometí a Nepolis que no me acercaría a ningún espejo de aspecto sospechoso...)",
  ui_story_5087_50870502_26_dialog_content = "Nikinis... ¿Puedes oírme?",
  ui_story_5087_50870502_27_dialog_content = "...",
  ui_story_5087_50870502_28_dialog_content = "Sí, pero ¿quién eres tú? ¿Por qué sigues apareciendo dentro de los espejos?",
  ui_story_5087_50870502_29_dialog_content = "Excelente, el espejo finalmente ha llegado a tus manos... Por favor... ¡No le digas a nadie sobre esto!",
  ui_story_5087_50870600_1_dialog_content = "<color=#e8d9bb>La noche cae, y una ventisca aullante cubre el cielo de nieve. Incluso las sombras de las llamas dentro de la chimenea parecen parpadear con inquietud.</color>",
  ui_story_5087_50870600_2_dialog_content = "(Me pregunto cómo nuestros padres están soportando una tormenta como esta... Seguramente no se quedarían afuera en noches como esta, ¿supongo?)",
  ui_story_5087_50870600_3_dialog_content = "¡Finalmente terminé de informar todo a la reina, Nikinis! ¡Estaba realmente complacida con nuestros resultados!",
  ui_story_5087_50870600_4_dialog_content = "Eso es maravilloso. Ahora finalmente podemos ir a casa y pasar un tiempo con nuestros padres.",
  ui_story_5087_50870600_5_dialog_content = "Oh... Cierto...",
  ui_story_5087_50870600_6_dialog_content = "¡Nepolis! ¡Nikinis! ¡Oh, gracias a Dios que todavía no te has ido!",
  ui_story_5087_50870600_7_dialog_content = "Acaba de llegar una carta de tus padres. Dicen que todavía están cumpliendo las órdenes de la reina, por lo que no podrán regresar durante unos días más.",
  ui_story_5087_50870600_8_dialog_content = "En una tormenta como esta, es mejor si tú tampoco vuelves ahora mismo. No querrías quedar atrapado en la nieve, ¿verdad?",
  ui_story_5087_50870600_9_dialog_content = "Pero.",
  ui_story_5087_50870600_10_dialog_content = "Tiene razón, Nikinis. Intentar navegar en esta ventisca por la noche sería demasiado peligroso.",
  ui_story_5087_50870600_11_dialog_content = "Además, nuestros padres ni siquiera están en casa ahora mismo. Pasemos la noche en algún lugar cercano, ¿de acuerdo?",
  ui_story_5087_50870600_12_dialog_content = "Si tú lo dices...",
  ui_story_5087_50870600_13_dialog_content = "(No recuerdo haber visto a nuestros padres en el Palacio de Invierno antes... ¿Podría ser esto un efecto secundario de mi enfermedad?)",
  ui_story_5087_50870600_14_dialog_content = "(Si hubieran estado trabajando para la reina, seguramente Nepolis y yo los habríamos visto en el palacio, ¿verdad?)",
  ui_story_5087_50870600_15_dialog_content = "(¿Pero realmente están cumpliendo las órdenes de la reina? ¿Cuándo empezaron a hacer eso? ¿Por qué no recuerdo nada al respecto?)",
  ui_story_5087_50870600_16_dialog_content = "(La única cosa que puedo recordar claramente es que nos llevaron al Palacio de Invierno para tratamiento.)",
  ui_story_5087_50870600_17_dialog_content = "(Después de eso, apenas podía recordar sus caras...)",
  ui_story_5087_50870600_18_dialog_content = "(¿Podría ser que mi enfermedad afectó mis recuerdos de alguna manera?)",
  ui_story_5087_50870600_19_dialog_content = "(Aunque no recuerdo nada de esto, Nepolis y ese mensajero hablan de ello como si fuera completamente normal. Casi se siente como...)",
  ui_story_5087_50870600_20_dialog_content = "(Este mundo está envuelto en una capa de ilusión.)",
  ui_story_5087_50870600_21_dialog_content = "(No... Debo estar imaginando cosas. Mi hermana es real, sin duda alguna.)",
  ui_story_5087_50870600_22_dialog_content = "... ¡Ah!",
  ui_story_5087_50870600_23_dialog_content = "¿Qué es, Nepolis?",
  ui_story_5087_50870600_24_dialog_content = "¡Mi cabello! ¡Se quedó atrapado en una de las ramas del árbol! ¡Ayúdame, Nikinis!",
  ui_story_5087_50870600_25_dialog_content = "Honestamente... ¿Cómo lograste atascarla en una rama? ¡Deja de dar vueltas antes de que te lastimes!",
  ui_story_5087_50870600_26_dialog_content = "Es porque vi una linda ardillita justo ahora. Me acerqué para verla más de cerca, pero entonces...",
  ui_story_5087_50870600_27_dialog_content = "Lograste hacer algunas cosas bastante increíbles cuando no estaba prestando atención, ¿sabes?",
  ui_story_5087_50870600_28_dialog_content = "Tienes razón para hablar, Nikinis. Has estado descubriendo todo tipo de poderes y emociones últimamente, todo sin que yo me dé cuenta...",
  ui_story_5087_50870600_29_dialog_content = "Solíamos ser uno y lo mismo, ¿recuerdas? Nuestros corazones y almas estaban conectados, y compartíamos todo, desde nuestra apariencia y talentos hasta nuestros gustos y disgustos.",
  ui_story_5087_50870600_30_dialog_content = "Ver cómo te conviertes lentamente en alguien más a veces me hace sentir tan solo...",
  ui_story_5087_50870600_31_dialog_content = "Mira el ramo que conseguiste: los narcisos están atados estrechamente con rosas amarillas y nomeolvides, pero sin ningún lirio...",
  ui_story_5087_50870600_32_dialog_content = "Nepolis... ¿De qué diablos estás hablando? ¡No hay otro par de hermanos en el mundo más parecidos que nosotros dos! ¿Cuándo nos volvimos \"diferentes\" para ti?",
  ui_story_5087_50870600_33_dialog_content = "Prometí nunca acercarme a ese espejo de nuevo, así que por favor no te preocupes por mí, ¿de acuerdo?",
  ui_story_5087_50870600_34_dialog_content = "... ¡Ahí! Tu cabello está desenredado ahora. Sal de debajo de ese árbol.",
  ui_story_5087_50870600_35_dialog_content = "¡Dulce, dulce libertad!",
  ui_story_5087_50870600_36_dialog_content = "... Gracias, Nikinis. Sin ti, no sé qué haría.",
  ui_story_5087_50870600_37_dialog_content = "Entonces, simplemente deja de decir cosas como \"No soy de ayuda para mi hermana...\"",
  ui_story_5087_50870600_38_dialog_content = "Tener a tu lado es la mayor bendición que podría pedir.",
  ui_story_5087_50870600_39_dialog_content = "(Nepolis es real, y yo también. No hay duda al respecto.)",
  ui_story_5087_50870600_40_dialog_content = "(Es por eso... tengo que destruir este espejo misterioso.)",
  ui_story_5087_50870600_41_dialog_content = "Nikinis... ¿Eres tú?",
  ui_story_5087_50870600_42_dialog_content = "(... ¡Ha vuelto de nuevo!)",
  ui_story_5087_50870600_43_dialog_content = "Por favor, no me hables más. ¡No quiero que mi hermana siga sufriendo así!",
  ui_story_5087_50870600_44_dialog_content = "Solo escúchame, Nikinis! Tienes que ir... y encontrar... solo entonces...",
  ui_story_5087_50870600_45_dialog_content = "¿Ir a dónde? ¿Qué se supone que debo encontrar?",
  ui_story_5087_50870600_46_dialog_content = "¿Quién eres tú, y por qué sigues hablando conmigo a través de los espejos?",
  ui_story_5087_50870600_47_dialog_content = "Yo soy... Estás en un... Solo por... puedes...",
  ui_story_5087_50870600_48_dialog_content = "... No puedo entender nada de lo que dices. ¡Tu voz sigue desvaneciéndose en el peor momento!",
  ui_story_5087_50870600_49_dialog_content = "¡Es esa cosa! ¡Sigue interfiriendo con nosotros! Incluso después de romper el... nunca se detuvo. Todavía está bloqueando... ¡Urgh!",
  ui_story_5087_50870600_50_dialog_content = "\"¿Rompiendo\"? ¿Estás hablando del Espejo Northland? ¿Sabes quién lo hizo? Espera, ¿cómo sabes que el espejo está roto?",
  ui_story_5087_50870600_51_dialog_content = "¿Podría ser... que tú fuiste el que robó el Espejo de Northland?",
  ui_story_5087_50870600_52_dialog_content = "<color=#e8d9bb>Antes de que la persona en el espejo pueda responder, la ventisca golpea aún más fuerte la cabaña, haciendo temblar las ventanas en sus marcos.</color>",
  ui_story_5087_50870600_53_dialog_content = "<color=#e8d9bb>Nikinis baja la cabeza una vez más. El espejo en sus manos no refleja nada más que las llamas parpadeantes de la chimenea y la nieve que gira afuera.</color>",
  ui_story_5087_50870700_1_dialog_content = "<color=#e8d9bb>La nieve continúa cayendo mientras nubes sombrías se ciernen sobre Northland, su apariencia oscura y solemne refleja directamente el estado de ánimo de Nikinis.</color>",
  ui_story_5087_50870700_2_dialog_content = "<color=#e8d9bb>Un hogar inalcanzable, un misterio irresoluble y una memoria incierta... Todas estas cosas pesan mucho en su corazón.</color>",
  ui_story_5087_50870700_3_dialog_content = "<color=#e8d9bb>Su único rayo de esperanza es el espejo en sus manos, que casi destruyó.</color>",
  ui_story_5087_50870700_4_dialog_content = "(La persona en el espejo no parece que vaya a regresar pronto...)",
  ui_story_5087_50870700_5_dialog_content = "(¿Realmente alguien está interfiriendo con nuestra comunicación? Quizás sea la persona que rompió el espejo en primer lugar.)",
  ui_story_5087_50870700_6_dialog_content = "(La persona en el espejo quiere que haga algo... ¿Pero por qué? ¿Están peleando con quien rompió el espejo? Las preguntas nunca parecen terminar...)",
  ui_story_5087_50870700_7_dialog_content = "Nikinis! ¡Tenemos problemas!",
  ui_story_5087_50870700_8_dialog_content = "¿Q-Qué es?",
  ui_story_5087_50870700_9_dialog_content = "¿Eh? ¿Por qué pareces tan nervioso? No me digas que recibiste una carta de amor o algo así.",
  ui_story_5087_50870700_10_dialog_content = "¡Para nada! Incluso si lo hiciera, no te lo ocultaría—",
  ui_story_5087_50870700_11_dialog_content = "Nunca te dejaría preocuparte por algo así, Nepolis. Confía en mí.",
  ui_story_5087_50870700_12_dialog_content = "... No tienes que defenderte así, ¿sabes? Tus cartas de amor son tu propio asunto, después de todo.",
  ui_story_5087_50870700_13_dialog_content = "¡No hay carta de amor!",
  ui_story_5087_50870700_14_dialog_content = "¡O-Okay, te creo! Ahora solo escúchame, acaba de suceder algo realmente grande—",
  ui_story_5087_50870700_15_dialog_content = "¡La reina acaba de publicar un retrato del ladrón del espejo!",
  ui_story_5087_50870700_16_dialog_content = "¿Qué? ¿Dónde?",
  ui_story_5087_50870700_17_dialog_content = "¿Oh? No esperaba que te preocuparas tanto por eso. Ven conmigo.",
  ui_story_5087_50870700_18_dialog_content = "Queen Bethlehem ha descubierto la identidad del ladrón y ha publicado un retrato de ellos para que todos lo vean.",
  ui_story_5087_50870700_19_dialog_content = "A partir de hoy, las fronteras de Northland estarán selladas y sus fuerzas se centrarán en la captura del ladrón. ¡Se anima a todos los residentes de Northland a informar cualquier actividad sospechosa de inmediato!",
  ui_story_5087_50870700_20_dialog_content = "¿Están cerrando las fronteras? Su Majestad raramente moviliza el reino de esta manera...",
  ui_story_5087_50870700_21_dialog_content = "¿No viste lo que pasó esta mañana? ¡El Palacio de Invierno prácticamente envió un ejército para cazar a este ladrón!",
  ui_story_5087_50870700_22_dialog_content = "Tiene sentido para mí. Después de todo, no cualquiera puede colarse en la bóveda del tesoro del Palacio de Invierno.",
  ui_story_5087_50870700_23_dialog_content = "Incluso una sola pieza de esos reliquias es suficientemente poderosa para arrasar cien aldeas. La reina solo está haciendo esto por nuestro bien.",
  ui_story_5087_50870700_24_dialog_content = "Echa un vistazo a este retrato, ¡aparentemente la ladrona es una pequeña niña! ¿Cómo logró un niño entrar al Palacio de Invierno?",
  ui_story_5087_50870700_25_dialog_content = "(¿Una niña? No me digas...)",
  ui_story_5087_50870700_26_dialog_content = "¡Perdóname! Pasando—",
  ui_story_5087_50870700_27_dialog_content = "(Lo sabía... ¡Era ella!)",
  ui_story_5087_50870700_28_dialog_content = "Tú también estás sorprendido, ¿no es así Nikinis? Resulta que el ladrón más buscado de Northland es solo una pequeña niña adorable...",
  ui_story_5087_50870700_29_dialog_content = "¡T-Tengo que irme, Nepolis!",
  ui_story_5087_50870700_30_dialog_content = "¿Eh? Espera, Nikinis, la reina nos encargó otra misión—",
  ui_story_5087_50870700_31_dialog_content = "¡Oye! ¿Estás ahí dentro? ¡Por favor di algo!",
  ui_story_5087_50870700_32_dialog_content = "(Sin respuesta... ¿Cómo hice aparecer a la persona en el espejo la última vez? ¡Eso es! Fue cuando pensé en usar Luminatics para destruirlo!)",
  ui_story_5087_50870700_33_dialog_content = "(Voy a intentar infundir el espejo con Lumina primero...)",
  ui_story_5087_50870700_34_dialog_content = "¡Nikinis!",
  ui_story_5087_50870700_35_dialog_content = "¡Estás aquí! Dime, ¿estás trabajando con una pequeña niña llamada Shaya?",
  ui_story_5087_50870700_36_dialog_content = "Ustedes dos fueron los que robaron el Espejo de Northland, ¿no es así?",
  ui_story_5087_50870700_37_dialog_content = "... Es cierto. Shaya es en realidad... Porque ella... y entró... por su cuenta...",
  ui_story_5087_50870700_38_dialog_content = "El Espejo del Norte es el pasadizo que preparamos para ti... pero fue roto por...",
  ui_story_5087_50870700_39_dialog_content = "Debe restaurarse primero... por eso necesitamos tu ayuda.",
  ui_story_5087_50870700_40_dialog_content = "Enviamos a Shaya para que te entregara este espejo, para que pudiéramos comunicarnos.",
  ui_story_5087_50870700_41_dialog_content = "¡¿De qué estás hablando?! Dime lo que estás planeando.",
  ui_story_5087_50870700_42_dialog_content = "No puedo responderte ahora mismo. Siempre que intento decirte algo... bloqueado.",
  ui_story_5087_50870700_43_dialog_content = "Encuentra a Shaya, y ella te lo dirá todo... ¡Solo ella puede ayudarte ahora!",
  ui_story_5087_50870700_44_dialog_content = "<color=#e8d9bb>La persona en el espejo desaparece con un destello.</color>",
  ui_story_5087_50870700_45_dialog_content = "(El juicio de Su Majestad no estaba equivocado después de todo... La que robó el Espejo de Northland fue Shaya.)",
  ui_story_5087_50870700_46_dialog_content = "(No solo eso, ella y la persona en el espejo están tramando algo juntos.)",
  ui_story_5087_50870700_47_dialog_content = "(Pero ¿por qué? No sentí ninguna animosidad de Shaya o de este espejo...)",
  ui_story_5087_50870700_48_dialog_content = "...",
  ui_story_5087_50870700_49_dialog_content = "(Mantendré el espejo fuera de la vista por ahora. Nepolis volverá en cualquier segundo.)",
  ui_story_5087_50870700_50_dialog_content = "(No puedo creer que le esté ocultando un secreto tan grande... Al confiar en el espejo, ¿estoy poniendo más distancia entre nosotros?)",
  ui_story_5087_50870700_51_dialog_content = "Nikinis! ¿Cómo pudiste salir corriendo por tu cuenta así?",
  ui_story_5087_50870700_52_dialog_content = "... Lo siento.",
  ui_story_5087_50870700_53_dialog_content = "La reina nos ha ordenado capturar al ladrón del espejo! No hay tiempo que perder, así que agarra tu abrigo y botas—",
  ui_story_5087_50870700_54_dialog_content = "¡Oh! Lo siento, ¡estaré allí mismo! Gracias por avisarme... Lo siento por huir hace un momento.",
  ui_story_5087_50870700_55_dialog_content = "... ¿Por qué te disculpas tanto? Somos hermanas, ¿recuerdas?",
  ui_story_5087_50870700_56_dialog_content = "Eres la persona más importante en mi vida. Pase lo que pase, eso nunca cambiará.",
  ui_story_5087_50870800_1_dialog_content = "Iré a comprobar por allí, Nepolis.",
  ui_story_5087_50870800_2_dialog_content = "Entonces miraré por aquí. Mantente en guardia.",
  ui_story_5087_50870800_3_dialog_content = "Estaré bien. Además, sé que vendrás a rescatarme tan pronto como sientas que estoy en problemas.",
  ui_story_5087_50870800_4_dialog_content = "Como gemelos, estamos conectados en mente y alma, ¿recuerdas?",
  ui_story_5087_50870800_5_dialog_content = "...",
  ui_story_5087_50870800_6_dialog_content = "(Este lugar debería ser lo suficientemente seguro.)",
  ui_story_5087_50870800_7_dialog_content = "¿Hola, estás ahí?",
  ui_story_5087_50870800_8_dialog_content = "¿Qué es, Nikinis? ¿Lograste encontrar a Shaya?",
  ui_story_5087_50870800_9_dialog_content = "Aún no, no. Mi hermana y yo la estamos buscando en este momento, junto con el resto del reino.",
  ui_story_5087_50870800_10_dialog_content = "No puedo recordar un momento en el que todo Northland se movilizó para cazar a un solo ladrón. Algo acerca de este mundo no parece correcto después de todo...",
  ui_story_5087_50870800_11_dialog_content = "Eso es porque tú eres... No te preocupes por Shaya, sin embargo. Después de todo, ella es... Las personas ordinarias no deberían representar una amenaza para ella.",
  ui_story_5087_50870800_12_dialog_content = "¡Escúchame, espejo! Yo...",
  ui_story_5087_50870800_13_dialog_content = "Quiero contarle a mi hermana todo lo que sé sobre ti y Shaya...",
  ui_story_5087_50870800_14_dialog_content = "¿Eh? Yo... Yo no sé si eso es una buena idea...",
  ui_story_5087_50870800_15_dialog_content = "Mi hermana y yo somos uno y lo mismo.",
  ui_story_5087_50870800_16_dialog_content = "¿Ah?",
  ui_story_5087_50870800_17_dialog_content = "Desde que llegamos al mundo, siempre hemos estado juntos. Como dos flores plantadas una al lado de la otra, crecimos y florecimos de la misma manera exacta.",
  ui_story_5087_50870800_18_dialog_content = "No puedo explicar por qué, pero sé que tú y Shaya no son malas personas. Quizás sea solo mi intuición...",
  ui_story_5087_50870800_19_dialog_content = "Y si lo es, mi hermana compartirá la misma intuición que la mía. No importa lo que estés planeando, ella no se interpondrá en tu camino.",
  ui_story_5087_50870800_20_dialog_content = "De hecho, ella te ayudará.",
  ui_story_5087_50870800_21_dialog_content = "... ¿Estás realmente tan seguro?",
  ui_story_5087_50870800_22_dialog_content = "Positivo. Eso es porque ya estoy considerando lo mismo.",
  ui_story_5087_50870800_23_dialog_content = "Solo necesito mirar en mi propio corazón para saber cuál será la elección de mi hermana.",
  ui_story_5087_50870800_24_dialog_content = "... Entiendo.",
  ui_story_5087_50870800_25_dialog_content = "Tengo una solicitud más. Queen Bethlehem es quien ordenó la captura de Shaya, lo que significa que debe saber algo.",
  ui_story_5087_50870800_26_dialog_content = "¿Estaría bien si también le contara sobre—",
  ui_story_5087_50870800_27_dialog_content = "¡Nunca!",
  ui_story_5087_50870800_28_dialog_content = "?",
  ui_story_5087_50870800_29_dialog_content = "Eso \"Queen Bethlehem\" es... Ella no es... así que no puedes...",
  ui_story_5087_50870800_30_dialog_content = "No puedo escuchar lo que estás diciendo. Creo que la interferencia está empeorando.",
  ui_story_5087_50870800_31_dialog_content = "¡Ugh! ¿Cómo se supone que te lo diga... No creas... Falso!",
  ui_story_5087_50870800_32_dialog_content = "¿Qué es falso? ¿La carta de ese mensajero? ¿La historia sobre mis padres? ¿Mis recuerdos?",
  ui_story_5087_50870800_33_dialog_content = "¿O podría ser... la reina?",
  ui_story_5087_50870800_34_dialog_content = "¡Muy mal!",
  ui_story_5087_50870800_35_dialog_content = "¿Su Majestad es una impostora?",
  ui_story_5087_50870800_36_dialog_content = "¡Sí! ¡Es verdad! Ella... Su objetivo es...",
  ui_story_5087_50870800_37_dialog_content = "... ¡Alto ahí!",
  ui_story_5087_50870800_38_dialog_content = "?",
  ui_story_5087_50870800_39_dialog_content = "¡Urgh!",
  ui_story_5087_50870800_40_dialog_content = "¡Finalmente te atrapé! ¡Vamos a ver cómo huyes ahora!",
  ui_story_5087_50870800_41_dialog_content = "¿Qué es, Nepolis? ¡Ah! Eres tú... Shaya...",
  ui_story_5087_50870800_42_dialog_content = "Atrapé a esta pequeña ladrona furtiva acechándote desde los árboles. ¡Definitivamente tramaba algo siniestro!",
  ui_story_5087_50870800_43_dialog_content = "¡Pero no te preocupes, la atrapé antes de que pudiera hacer su movimiento! ¡Estás a salvo ahora!",
  ui_story_5087_50870800_44_dialog_content = "...",
  ui_story_5087_50870800_45_dialog_content = "Nikinis... Ayúdame...",
  ui_story_5087_50870800_46_dialog_content = "¿Qué? ¿U-Ustedes se conocen? ¿Cuándo ocurrió eso? ¿Y por qué no me informaron al respecto?",
  ui_story_5087_50870800_47_dialog_content = "Nepolis... lo siento mucho.",
  ui_story_5087_50870800_48_dialog_content = "¡Ah! No te estaba culpando—",
  ui_story_5087_50870800_49_dialog_content = "Pero no te preocupes, te lo diré todo ahora. No te ocultaré nada nunca más, lo prometo.",
  ui_story_5087_50870800_50_dialog_content = "Después de esto... necesitaré tu sabiduría.",
  ui_story_5087_50870900_1_dialog_content = "¿Queen Bethlehem es un impostor?",
  ui_story_5087_50870900_2_dialog_content = "Sí. Ella no es más que una ilusión de sombras, por eso su reacción es tan agresiva.",
  ui_story_5087_50870900_3_dialog_content = "Movilizar un reino entero para aprehender a un solo ladrón... es un uso extremadamente ineficiente de su poder.",
  ui_story_5087_50870900_4_dialog_content = "La verdadera reina habría pensado en algo mucho más ingenioso.",
  ui_story_5087_50870900_5_dialog_content = "(Incluso después de conocerla por segunda vez, todavía creo que hay algo único en Shaya.)",
  ui_story_5087_50870900_6_dialog_content = "(A pesar de ser una niña tan joven, tiene un aire de rectitud sobre ella, y no tiene reparos en criticar a la reina.)",
  ui_story_5087_50870900_7_dialog_content = "Es cierto que los métodos de Su Majestad han sido algo diferentes últimamente, pero eso apenas es una razón para sospechar de ella...",
  ui_story_5087_50870900_8_dialog_content = "Si lo que dijiste es cierto, Shaya, entonces ¿dónde está la verdadera reina?",
  ui_story_5087_50870900_9_dialog_content = "... En general, Bethlehem tiende a pasar su tiempo en un mundo diferente: el mundo al otro lado del espejo de Northland.",
  ui_story_5087_50870900_10_dialog_content = "... ¿Estás diciendo que hay un mundo completamente diferente detrás del Espejo Northland?",
  ui_story_5087_50870900_11_dialog_content = "¿Significa esto que tu razón para robar el espejo era viajar a este otro mundo y encontrar el verdadero Queen Bethlehem?",
  ui_story_5087_50870900_12_dialog_content = "Tu razonamiento va por el camino correcto... Es cierto, necesito ir allá.",
  ui_story_5087_50870900_13_dialog_content = "El Espejo de Northland es el pasadizo perfecto para viajar entre ambos mundos.",
  ui_story_5087_50870900_14_dialog_content = "Pero ahora que está roto, debe repararse antes de que pueda hacerlo.",
  ui_story_5087_50870900_15_dialog_content = "Nikinis, tienes una poderosa afinidad con el Espejo de Northland. Para restaurarlo a su estado original, necesito tu ayuda.",
  ui_story_5087_50870900_16_dialog_content = "¿Estás dispuesto a ayudarme? Naturalmente, también estaría dispuesto a ayudar a los dos.",
  ui_story_5087_50870900_17_dialog_content = "El que está en el espejo puede servir como tu guía. También existe en el otro mundo, y su objetivo no es diferente al mío.",
  ui_story_5087_50870900_18_dialog_content = "...",
  ui_story_5087_50870900_19_dialog_content = "¿Qué piensas, Nepolis? Sé que no quieres que me acerque a ese espejo.",
  ui_story_5087_50870900_20_dialog_content = "Pero quieres hacer esto, ¿no?",
  ui_story_5087_50870900_21_dialog_content = "(Yo...)",
  ui_story_5087_50870900_22_dialog_content = "... Lo siento, Nikinis. Parece que mi celos te hicieron preocuparte.",
  ui_story_5087_50870900_23_dialog_content = "Puedo decir que has estado pensando en mí y en mis sentimientos durante los últimos días...",
  ui_story_5087_50870900_24_dialog_content = "Aunque soy el mayor, apenas actúo como tal.",
  ui_story_5087_50870900_25_dialog_content = "¡Eso no es todo! Tú y yo pensamos exactamente lo mismo. Todo lo que quiero es estar contigo en mente y alma, como siempre...",
  ui_story_5087_50870900_26_dialog_content = "... ¡Es lo que más quiero en todo el mundo!",
  ui_story_5087_50870900_27_dialog_content = "Pero eso no me da el derecho de despojarte de tus alas.",
  ui_story_5087_50870900_28_dialog_content = "!",
  ui_story_5087_50870900_29_dialog_content = "...",
  ui_story_5087_50870900_30_dialog_content = "La verdad es que me está costando mucho creer todo lo que nos acabas de contar, Shaya.",
  ui_story_5087_50870900_31_dialog_content = "... Entiendo.",
  ui_story_5087_50870900_32_dialog_content = "Pero mi hermana siempre ha dado mucha importancia a ese espejo.",
  ui_story_5087_50870900_33_dialog_content = "Después de escuchar la historia de la reina sobre cómo fuimos curados, estoy convencido de que Nikinis y el espejo comparten un destino inextricable.",
  ui_story_5087_50870900_34_dialog_content = "Me sentí solo porque solo mi hermana fue elegida, y así comencé a actuar por envidia...",
  ui_story_5087_50870900_35_dialog_content = "Fue un error de mi parte hacer eso. Como la hermana mayor, se supone que debo cuidarla y ayudarla a crecer.",
  ui_story_5087_50870900_36_dialog_content = "Népolis...",
  ui_story_5087_50870900_37_dialog_content = "... Tienes un alma bastante increíble, Nepolis.",
  ui_story_5087_50870900_38_dialog_content = "Quizás te he subestimado todo este tiempo.",
  ui_story_5087_50870900_39_dialog_content = "Entonces, Shaya—",
  ui_story_5087_50870900_40_dialog_content = "¡Solo dinos qué necesitamos hacer para ayudarte a restaurar el Espejo de Northland!",
  ui_story_5087_50871000_1_dialog_content = "...",
  ui_story_5087_50871000_2_dialog_content = "...",
  ui_story_5087_50871000_3_dialog_content = "Hmm... Una vez que crucemos esta montaña, deberíamos llegar al Palacio de Invierno.",
  ui_story_5087_50871000_4_dialog_content = "...",
  ui_story_5087_50871000_5_dialog_content = "...",
  ui_story_5087_50871000_6_dialog_content = "¡No podemos seguir avanzando en silencio! Shaya, sé que estás muy insatisfecha con la falsa reina en este momento—",
  ui_story_5087_50871000_7_dialog_content = "Estoy extremadamente insatisfecho, de hecho. ¡Ella movilizó a cada soldado en el reino para buscar a un ladrón!",
  ui_story_5087_50871000_8_dialog_content = "Nepolis, sé que todavía no estás convencido—",
  ui_story_5087_50871000_9_dialog_content = "¡Por supuesto que no estoy convencido!",
  ui_story_5087_50871000_10_dialog_content = "Es una cosa restaurar el Espejo de Northland, o infiltrarse en la bóveda del tesoro del Palacio de Invierno...",
  ui_story_5087_50871000_11_dialog_content = "Pero \"¿cómo unir nuestras fuerzas y derrotar a la reina si nos descubre\"? ¡Cómo te atreves a incluir eso en tu plan!",
  ui_story_5087_50871000_12_dialog_content = "¡Incluso hiciste un dibujo para esto!",
  ui_story_5087_50871000_13_dialog_content = "¿Cómo conoces tan bien las debilidades de la reina, Shaya? ¿Estás segura de que no estás tramando algo más?",
  ui_story_5087_50871000_14_dialog_content = "... Ahora entiendo el dolor de no poder decir la verdad.",
  ui_story_5087_50871000_15_dialog_content = "Nikinis! ¿No recuerdas el riesgo que Su Majestad tomó para salvar nuestras vidas?",
  ui_story_5087_50871000_16_dialog_content = "(Yo...)",
  ui_story_5087_50871000_17_dialog_content = "¿Cómo puedes creer tan fácilmente cada palabra que esta mujer dice sobre nuestra Queen siendo una impostora?",
  ui_story_5087_50871000_18_dialog_content = "Nepolis, te elogio por ser tan leal a Bethlehem—",
  ui_story_5087_50871000_19_dialog_content = "¡Deja de dirigirte a la reina solo por su nombre!",
  ui_story_5087_50871000_20_dialog_content = "Pero incluso el verdadero Bethlehem estaría asombrado por tu terquedad en este momento.",
  ui_story_5087_50871000_21_dialog_content = "¡Cómo te atreves a decir eso sobre Su Majestad! Una reina digna y noble como ella nunca—",
  ui_story_5087_50871000_22_dialog_content = "Lo haría. Confía en mí.",
  ui_story_5087_50871000_23_dialog_content = "Ustedes dos...",
  ui_story_5087_50871000_24_dialog_content = "Tampoco sé por qué tienes tanta prisa, Nikinis.",
  ui_story_5087_50871000_25_dialog_content = "Infiltrar la bóveda del tesoro requiere una planificación e investigación cuidadosas. Además, el \"Espejo de Northland\" no va a ninguna parte.",
  ui_story_5087_50871000_26_dialog_content = "¿Por qué insistes en irrumpir allí hoy? Y si la reina nos encuentra, ¿estás realmente preparado para luchar contra ella?",
  ui_story_5087_50871000_27_dialog_content = "Esa cosa no es tu reina.",
  ui_story_5087_50871000_28_dialog_content = "Eres el único que lo dice.",
  ui_story_5087_50871000_29_dialog_content = "La mayoría de los soldados del Palacio de Invierno están buscándome por todo el país en este momento. No tendremos otra oportunidad como esta para entrar en la bóveda.",
  ui_story_5087_50871000_30_dialog_content = "Entonces sabes que también estamos \"entrando a la fuerza\", ¿no es así?",
  ui_story_5087_50871000_31_dialog_content = "¡Nepolis! ¡Shaya! ¡Deja de pelear ahora mismo!",
  ui_story_5087_50871000_32_dialog_content = "Es cierto, tengo prisa por hacer esto. Pero Nepolis, tienes que entender que algo va terriblemente mal con este mundo en este momento...",
  ui_story_5087_50871000_33_dialog_content = "...",
  ui_story_5087_50871000_34_dialog_content = "¿Qué exactamente está mal con eso?",
  ui_story_5087_50871000_35_dialog_content = "Muchas cosas... Por ejemplo, ¿cuándo empezaron nuestros padres a trabajar para el Palacio de Invierno? Tú y todos los demás parecen saberlo, sin embargo, no tengo ningún recuerdo de ello en absoluto...",
  ui_story_5087_50871000_36_dialog_content = "¿Qué? ¿Podría ser esto un efecto secundario de tu enfermedad? ¿Te sientes mal de nuevo?",
  ui_story_5087_50871000_37_dialog_content = "(Yo...)",
  ui_story_5087_50871000_38_dialog_content = "(¿Qué debo hacer? Por primera vez en mi vida... No sé cómo decirle a mi hermana lo que estoy pensando.)",
  ui_story_5087_50871000_39_dialog_content = "(Parece tan preocupada por mí. ¿Soy yo el que está siendo demasiado caprichoso con esto?)",
  ui_story_5087_50871000_40_dialog_content = "... Me alegro de que estés bien. Solo... iré a explorar adelante por ahora.",
  ui_story_5087_50871000_41_dialog_content = "Ninguno de ustedes está equivocado, así que por favor no dejen que les moleste. Es solo que solo tú eres capaz de sentir ciertas cosas.",
  ui_story_5087_50871000_42_dialog_content = "Pero por qué... ¿Por qué soy el único que puede sentirlos?",
  ui_story_5087_50871000_43_dialog_content = "Mi hermana y yo siempre hemos sido iguales. ¿Cuándo empezamos... a tener estas diferencias?",
  ui_story_5087_50871000_44_dialog_content = "Aunque ambos son tan puros y blancos como la nieve, un lirio y un narciso blanco siempre serán dos flores diferentes. Además...",
  ui_story_5087_50871000_45_dialog_content = "...",
  ui_story_5087_50871000_46_dialog_content = "Por favor dime, ¡Shaya! ¿Es solo mi imaginación, o realmente hay algo malo con este mundo?",
  ui_story_5087_50871000_47_dialog_content = "Aparte de que la reina es falsa, ¿hay algo más que no me estás diciendo?",
  ui_story_5087_50871000_48_dialog_content = "... Hay.",
  ui_story_5087_50871000_49_dialog_content = "!",
  ui_story_5087_50871000_50_dialog_content = "Pero sería imprudente de mi parte decírtelo ahora mismo.",
  ui_story_5087_50871000_51_dialog_content = "Una vez que lleguemos al Palacio de Invierno y restauremos el espejo, todo quedará claro.",
  ui_story_5087_50871000_52_dialog_content = "Tú... Tú no tienes una hermana, ¿verdad?",
  ui_story_5087_50871000_53_dialog_content = "... Yo sí.",
  ui_story_5087_50871000_54_dialog_content = "¿Tú haces?",
  ui_story_5087_50871000_55_dialog_content = "Aunque incluso según los estándares más generosos, está lejos de ser considerada una relación amistosa.",
  ui_story_5087_50871000_56_dialog_content = "Entonces, realmente envidio a Nepolis y a ti.",
  ui_story_5087_50871000_57_dialog_content = "... Quiero proteger a los dos, incluso si es solo por otro segundo.",
  ui_story_5087_50871000_58_dialog_content = "Tienes una idea equivocada, Shaya.",
  ui_story_5087_50871000_59_dialog_content = "¿Ah?",
  ui_story_5087_50871000_60_dialog_content = "Incluso si mi hermana y yo nacimos con una conexión telepática que nos otorgó conciencia de los pensamientos del otro—",
  ui_story_5087_50871000_61_dialog_content = "Todavía luchamos. Tú mismo lo has visto.",
  ui_story_5087_50871000_62_dialog_content = "!",
  ui_story_5087_50871000_63_dialog_content = "Pero eso es solo temporal. Es solo un poco de fricción que surge de una diferencia en sentimientos y experiencias.",
  ui_story_5087_50871000_64_dialog_content = "El hecho de que envidies la relación que tenemos es prueba de que no has renunciado a tu propia relación de hermandad...",
  ui_story_5087_50871000_65_dialog_content = "Todavía sueñas con arreglar las cosas con tu hermana.",
  ui_story_5087_50871000_66_dialog_content = "Mientras no te rindas, algún día, llegarás a entenderos... al menos eso es lo que creo.",
  ui_story_5087_50871000_67_dialog_content = "... Gracias, Nikinis. Lo tendré en cuenta.",
  ui_story_5087_50871000_68_dialog_content = "Nepolis se niega a moverse contra la falsa reina, así que separémonos una vez que estemos dentro del Palacio de Invierno.",
  ui_story_5087_50871000_69_dialog_content = "Descubriré cómo lidiar con la reina. Tú simplemente dirígete directamente a la bóveda del tesoro con tu hermana.",
  ui_story_5087_50871000_70_dialog_content = "¡No puedo permitirte hacer eso! Su Majestad es demasiado fuerte—",
  ui_story_5087_50871000_71_dialog_content = "No, es mejor así. Destacaremos si nos mantenemos juntos.",
  ui_story_5087_50871000_72_dialog_content = "Con la conexión que ustedes dos comparten, hacen un par mucho más eficiente cuando no me están arrastrando.",
  ui_story_5087_50871000_73_dialog_content = "Mantendré a la reina ocupada en secreto y te cubriré. Es más fácil hacer eso solo.",
  ui_story_5087_50871000_74_dialog_content = "Busca respuestas de la persona en el espejo si encuentras algún problema durante la operación.",
  ui_story_5087_50871000_75_dialog_content = "... Es mi compañero de más confianza, y será tu guía en el Palacio de Invierno.",
  ui_story_5087_50871101_1_dialog_content = "... Shaya se adelantó y se infiltró en el Palacio de Invierno. Mencionó algo sobre un pasadizo secreto al que solo ella podía entrar.",
  ui_story_5087_50871101_2_dialog_content = "¡Jajaja! Ahora está en forma de niña.",
  ui_story_5087_50871101_3_dialog_content = "?",
  ui_story_5087_50871101_4_dialog_content = "Ahora, es tu turno. La seguridad siempre es estricta en la entrada...",
  ui_story_5087_50871101_5_dialog_content = "Pero siempre vas y vienes del Palacio de Invierno, así que no es un problema, ¿verdad?",
  ui_story_5087_50871101_6_dialog_content = "...",
  ui_story_5087_50871101_7_dialog_content = "¡Yo creo que sí!",
  ui_story_5087_50871101_8_dialog_content = "Detener.",
  ui_story_5087_50871101_9_dialog_content = "Hola, soy Nikinis, y esto es Nepolis. Tenemos negocios en el Palacio de Invierno—",
  ui_story_5087_50871101_10_dialog_content = "La entrada está prohibida al público hasta que se capture al ladrón del espejo.",
  ui_story_5087_50871101_11_dialog_content = "(... ¿Qué?)",
  ui_story_5087_50871101_12_dialog_content = "No somos simplemente cualquiera. Encontramos el Espejo de Northland robado.",
  ui_story_5087_50871101_13_dialog_content = "Estamos bajo las órdenes de Su Majestad para rastrear al ladrón, y acabamos de descubrir una pista que requiere verificación cruzada en la biblioteca del palacio.",
  ui_story_5087_50871101_14_dialog_content = "¿Podrías dejarnos pasar? Todos estamos sirviendo a Su Majestad aquí.",
  ui_story_5087_50871101_15_dialog_content = "Oh... Hmm...",
  ui_story_5087_50871101_16_dialog_content = "Por supuesto, tu ayuda será recompensada. Visitaré con el fino té otorgado por Su Majestad, ¡y podemos disfrutarlo juntos!",
  ui_story_5087_50871101_17_dialog_content = "¿En serio? Ejem... Pensándolo bien, estás estrechamente relacionado con el robo y se te debería permitir la entrada.",
  ui_story_5087_50871101_18_dialog_content = "Puedes pasar.",
  ui_story_5087_50871101_19_dialog_content = "(¡Eso funcionó!)",
  ui_story_5087_50871101_20_dialog_content = "... Gire a la derecha más adelante, continúe recto, luego baje las escaleras.",
  ui_story_5087_50871101_21_dialog_content = "Mantén los ojos abiertos. Zarya a menudo se sienta junto a la ventana de la bahía para disfrutar de la vista. No dejes que te atrape.",
  ui_story_5087_50871101_22_dialog_content = "¿Zarya? ¿Quién es ese? Bueno, he mirado y no hay nadie allí.",
  ui_story_5087_50871101_23_dialog_content = "¿Zarya aún no aparece en el otro mundo? Oh, he dicho demasiado... ¡Ah! ¡Agáchate! ¡Los conejitos de Novio definitivamente se esconden en ese patio exterior!",
  ui_story_5087_50871101_24_dialog_content = "Mantén los ojos abiertos también mientras bajas las escaleras. Casi me envían seis pies bajo tierra por una capa de hielo que Noah dejó atrás...",
  ui_story_5087_50871101_25_dialog_content = "En serio, ¿quién eres tú? Estás actuando de manera tan secreta, pero posees un conocimiento extenso sobre la estructura y el personal del Palacio de Invierno... ¿Estás seguro de que no eres un espía?",
  ui_story_5087_50871101_26_dialog_content = "¡Confía en mí, soy una buena persona!",
  ui_story_5087_50871101_27_dialog_content = "... Todo será revelado una vez que el espejo esté reparado.",
  ui_story_5087_50871101_28_dialog_content = "... Humph.",
  ui_story_5087_50871101_29_dialog_content = "Bueno, ya hemos llegado hasta aquí, así que simplemente confiemos en él y en Shaya.",
  ui_story_5087_50871101_30_dialog_content = "Hablando de eso, no habríamos llegado aquí sin ti. Si estuviera solo, ni siquiera habría logrado entrar.",
  ui_story_5087_50871101_31_dialog_content = "Te preocupas por mis sentimientos de nuevo, ¿verdad?",
  ui_story_5087_50871101_32_dialog_content = "¡No no soy!",
  ui_story_5087_50871101_33_dialog_content = "Puedo percibir tus sentimientos, ¿recuerdas?",
  ui_story_5087_50871101_34_dialog_content = "...",
  ui_story_5087_50871101_35_dialog_content = "Nikinis, ¿recuerdas el trastorno de memoria que mencionaste? ¿Estás seguro de que no es un efecto secundario de tu enfermedad?",
  ui_story_5087_50871101_36_dialog_content = "Bueno... No lo sé, para ser honesto, pero algo me dice que hay más de lo que se ve a simple vista.",
  ui_story_5087_50871101_37_dialog_content = "Bueno entonces... Resolvamos todos los misterios. No importa lo que hagas, siempre estaré allí a tu lado.",
  ui_story_5087_50871101_38_dialog_content = "... Lo siento por siempre arrastrarte a las cosas...",
  ui_story_5087_50871101_39_dialog_content = "Para nada. Llegué a esta decisión después de mucha deliberación.",
  ui_story_5087_50871101_40_dialog_content = "Hice mucha reflexión en nuestro camino al Palacio de Invierno. Pensé en el pasado y en los eventos recientes ...",
  ui_story_5087_50871101_41_dialog_content = "Me di cuenta de que tal vez nunca fuimos tan similares, para empezar.",
  ui_story_5087_50871101_42_dialog_content = "!",
  ui_story_5087_50871101_43_dialog_content = "Prefiero un ambiente animado, pero a ti te gusta la paz y la tranquilidad. Me gustan los animales pequeños, pero tú prefieres leer...",
  ui_story_5087_50871101_44_dialog_content = "Puedo hacer que los guardias reales se hagan a un lado para nosotros, pero tú no puedes hacer lo mismo.",
  ui_story_5087_50871101_45_dialog_content = "¿Eh? Yo-Yo recogeré todo lo que me muestres...",
  ui_story_5087_50871101_46_dialog_content = "Jeje... Está bien. Se siente bastante bien saber que hay cosas que solo yo puedo lograr.",
  ui_story_5087_50871101_47_dialog_content = "Estoy seguro de que tendremos más discusiones en el futuro, porque después de todo no somos iguales. Es imposible que siempre estemos en la misma página.",
  ui_story_5087_50871101_48_dialog_content = "Pero no es gran cosa, ni siquiera si la conexión que compartimos desaparece un día.",
  ui_story_5087_50871101_49_dialog_content = "Mientras tenga mi boca para buscar tus pensamientos y un par de piernas para acercarme a ti...",
  ui_story_5087_50871101_50_dialog_content = "Nuestros corazones nunca estarán separados.",
  ui_story_5087_50871101_51_dialog_content = "¡Nepolis! Oh... Me alegra tanto saber que te sientes así...",
  ui_story_5087_50871101_52_dialog_content = "¡Eres el mejor! ¡Nunca me alejaré de tu lado! Boo-hoo...",
  ui_story_5087_50871101_53_dialog_content = "¡Oye! ¡Compórtate de acuerdo a tu edad! Estamos en el Palacio de Invierno...",
  ui_story_5087_50871101_54_dialog_content = "E-En realidad, acabo de tener una conversación similar con Shaya... ¡Espera un minuto! ¿Escuchaste nuestra conversación?",
  ui_story_5087_50871101_55_dialog_content = "¿Qué conversación?",
  ui_story_5087_50871101_56_dialog_content = "Lamento interrumpir, pero siento algo poderoso presionándome... El Espejo del Norte está cerca.",
  ui_story_5087_50871101_57_dialog_content = "El peligro puede estar acechando adelante, y podría ser incapaz de darte más orientación en cualquier momento—",
  ui_story_5087_50871101_58_dialog_content = "...Está bien.",
  ui_story_5087_50871101_59_dialog_content = "Entonces, esta es la bóveda del tesoro del Palacio de Invierno: la Sala de Reliquias.",
  ui_story_5087_50871101_60_dialog_content = "¿Ah? ¿Has estado aquí antes?",
  ui_story_5087_50871101_61_dialog_content = "Mi hermana y yo solíamos jugar al escondite aquí cuando éramos pequeñas. ¿Todavía recuerdas el tiempo en que estábamos recibiendo tratamiento en el Palacio de Invierno, Nepolis?",
  ui_story_5087_50871101_62_dialog_content = "...",
  ui_story_5087_50871101_63_dialog_content = "¿Nepolis?",
  ui_story_5087_50871101_64_dialog_content = "Están... viniendo.",
  ui_story_5087_50871101_65_dialog_content = "Graah!",
  ui_story_5087_50871102_1_dialog_content = "Huff... Huff... Estos son unos monstruos muy fuertes. ¿Qué hacen en el Palacio de Invierno?",
  ui_story_5087_50871102_2_dialog_content = "Lo resolveremos más tarde. ¡Entra en la Sala de Reliquias! ¡Apúrate!",
  ui_story_5087_50871102_3_dialog_content = "¡El Espejo de Northland! Sabía que te encontraría aquí...",
  ui_story_5087_50871102_4_dialog_content = "<color=#e8d9bb>El Espejo de Northland está visiblemente dañado, con grietas y huecos por todas partes.</color>",
  ui_story_5087_50871102_5_dialog_content = "<color=#e8d9bb>Aún así, todavía irradia un resplandor suave y gentil mientras innumerables sombras parpadean en la superficie agrietada del espejo.</color>",
  ui_story_5087_50871102_6_dialog_content = "(Esas figuras me dan una sensación tan familiar...)",
  ui_story_5087_50871102_7_dialog_content = "¡E-Ese espejo! ¿Eres tú Lady Nikinis?",
  ui_story_5087_50871102_8_dialog_content = "Cálmate. Soy Nikinis, y estoy aquí por orden de Queen Bethlehem.",
  ui_story_5087_50871102_9_dialog_content = "Sospecho que las reliquias antiguas son la fuente de la serie de eventos extraños que has encontrado recientemente.",
  ui_story_5087_50871102_10_dialog_content = "Como es un asunto de suma importancia, te pido que me cuentes todos los detalles.",
  ui_story_5087_50871102_11_dialog_content = "¡Mucho!",
  ui_story_5087_50871102_12_dialog_content = "¡Graaah!",
  ui_story_5087_50871102_13_dialog_content = "Monstruo vil... ¡Y-Yo te derribaré!",
  ui_story_5087_50871102_14_dialog_content = "Monstruo, vete.",
  ui_story_5087_50871102_15_dialog_content = "Graaah...",
  ui_story_5087_50871102_16_dialog_content = "¡Lady Nikinis! ¡G-Gracias por salvarme!",
  ui_story_5087_50871102_17_dialog_content = "Tu vida es algo puro y precioso. La próxima vez, di mi nombre antes de arriesgar tu vida en la batalla.",
  ui_story_5087_50871102_18_dialog_content = "Me escabullí de la fiesta de celebración otra vez... Todos deben pensar que soy arrogante y molesto.",
  ui_story_5087_50871102_19_dialog_content = "Pero realmente no tengo idea de cómo actuar allí. Todos parecen tan felices, y solo yo...",
  ui_story_5087_50871102_20_dialog_content = "¡Lady Nikinis!",
  ui_story_5087_50871102_21_dialog_content = "Eres de aquel entonces—",
  ui_story_5087_50871102_22_dialog_content = "Te vi escaparte, p-pero aún no he tenido la oportunidad de darte esto!",
  ui_story_5087_50871102_23_dialog_content = "Un ramo de narcisos y lirios...",
  ui_story_5087_50871102_24_dialog_content = "Escuché que son tus flores favoritas.",
  ui_story_5087_50871102_25_dialog_content = "¡Lady Nikinis, no puedo agradecerte lo suficiente por siempre luchar a nuestro lado y protegernos!",
  ui_story_5087_50871102_26_dialog_content = "(¿Fue eso... mi memoria justo ahora?)",
  ui_story_5087_50871102_27_dialog_content = "(¿Alguna vez fui tan impresionante y tranquilo? ¿Participé en tantos eventos importantes?)",
  ui_story_5087_50871102_28_dialog_content = "<color=#e8d9bb>Como si fuera atraída por sus recuerdos recuperados, Nikinis avanza hacia el Espejo de Northland y coloca su palma sobre él—</color>",
  ui_story_5087_50871102_29_dialog_content = "¡Está completo de nuevo! ... Realmente tienes una conexión especial con él, Nikinis.",
  ui_story_5087_50871102_30_dialog_content = "mmm...",
  ui_story_5087_50871102_31_dialog_content = "Esto es genial. ¡Ahora, solo queda el paso final!",
  ui_story_5087_50871102_32_dialog_content = "¿El paso final? ¿No dijiste que todo se revelará una vez que se repare el espejo?",
  ui_story_5087_50871102_33_dialog_content = "Nikinis, deberías haber logrado recuperar una parte de tus recuerdos mientras reparabas el espejo.",
  ui_story_5087_50871102_34_dialog_content = "Ahora... Todo lo que queda es <color=#FFB400>atravesar el espejo</color>!",
  ui_story_5087_50871102_35_dialog_content = "¿Qué? ¿Pasar al otro mundo?",
  ui_story_5087_50871102_36_dialog_content = "Exactamente. Es donde reside el verdadero Queen Bethlehem. ¡Tus recuerdos restantes y las respuestas que buscas también están más allá del espejo!",
  ui_story_5087_50871102_37_dialog_content = "no sé...",
  ui_story_5087_50871102_38_dialog_content = "Hazlo, Nikinis.",
  ui_story_5087_50871102_39_dialog_content = "¿Eh? ¿Quieres que entre en el espejo?",
  ui_story_5087_50871102_40_dialog_content = "Es cierto. Ya hemos llegado tan lejos. No podemos simplemente dar la vuelta y regresar a casa, ¿verdad?",
  ui_story_5087_50871102_41_dialog_content = "Debes recuperar tus recuerdos, descifrar todo y volver para contarme cada detalle.",
  ui_story_5087_50871102_42_dialog_content = "Si ese espejo se atreve a detenerte, no descansaré hasta traerte de vuelta, ¡y le mostraremos quién es el jefe!",
  ui_story_5087_50871102_43_dialog_content = "Entonces, solo hazlo. Es una promesa.",
  ui_story_5087_50871102_44_dialog_content = "Népolis...",
  ui_story_5087_50871102_45_dialog_content = "...",
  ui_story_5087_50871102_46_dialog_content = "Vamos, Nikinis.",
  ui_story_5087_50871102_47_dialog_content = "¡M-Me iré entonces, Nepolis!",
  ui_story_5087_50871102_48_dialog_content = "Ok.",
  ui_story_5087_50871102_49_dialog_content = "<color=#e8d9bb>El espejo brilla más brillante como si estuviera dando la bienvenida a Nikinis, y finalmente da ese paso—</color>",
  ui_story_5087_50871102_50_dialog_content = "<color=#e8d9bb>Efervescencia.</color>",
  ui_story_5087_50871102_51_dialog_content = "Uh... ¡Urgh! Ni siquiera... ¡lo pienses!",
  ui_story_5087_50871102_52_dialog_content = "¿Qué pasa, Nepolis?",
  ui_story_5087_50871102_53_dialog_content = "Estoy... bien... ¡Rápido...! ¡Urghhhh!",
  ui_story_5087_50871102_54_dialog_content = "...",
  ui_story_5087_50871102_55_dialog_content = "¡Nepolis! ¡Nepolis! ¿Estás bien?",
  ui_story_5087_50871102_56_dialog_content = "¡Nikinis! ¡Aléjate de tu hermana! Temo que ella—",
  ui_story_5087_50871102_57_dialog_content = "... Nikinis.",
  ui_story_5087_50871102_58_dialog_content = "¡Estoy justo aquí! ¿Cómo te sientes? ¿Estás herido en alguna parte?",
  ui_story_5087_50871102_59_dialog_content = "El otro lado del espejo... es extremadamente peligroso.",
  ui_story_5087_50871102_60_dialog_content = "¿Ah?",
  ui_story_5087_50871102_61_dialog_content = "No puedo dejarte ir a un lugar tan peligroso. Solo quédate a mi lado, ¿de acuerdo?",
  ui_story_5087_50871102_62_dialog_content = "P-Pero... Tú acabas de decir...",
  ui_story_5087_50871102_63_dialog_content = "Temo... Temo perderte... Una vez que atravieses el espejo, nunca volveré a verte.",
  ui_story_5087_50871102_64_dialog_content = "Todo lo que necesito eres tú, y creo que tú también sientes lo mismo, ¿verdad?",
  ui_story_5087_50871102_65_dialog_content = "Estarías tan solo sin mí... Ni siquiera serías capaz de enfrentarte a las sonrisas de la gente en una fiesta.",
  ui_story_5087_50871102_66_dialog_content = "!",
  ui_story_5087_50871102_67_dialog_content = "Cuanto más felices son los demás, más doloroso se vuelve para ti. Porque en el fondo, sabes que tu felicidad nunca volverá...",
  ui_story_5087_50871102_68_dialog_content = "Quédate conmigo, mi hermana... Mi Nikinis—",
  ui_story_5087_50871102_69_dialog_content = "Nikinis, no dejes que te engañe. ¡Esa ya no es tu hermana!",
  ui_story_5087_50871102_70_dialog_content = "¡Debes pasar a través del espejo! Estás dentro del <color=#FFB400>mundo espejo</color> creado por el Espejo del Norte! Y este lado—",
  ui_story_5087_50871102_71_dialog_content = "¡Este es el lugar donde realmente se encuentra la <color=#FFB400>realidad</color>!",
  ui_story_5087_50871102_72_dialog_content = "!",
  ui_story_5087_50871102_73_dialog_content = "¿No te has dado cuenta? ¡Nada en este mundo parece estar bien!",
  ui_story_5087_50871102_74_dialog_content = "Algo no está bien... Sí, no recuerdo que mis padres hayan trabajado alguna vez en el Palacio de Invierno...",
  ui_story_5087_50871102_75_dialog_content = "¡Porque fue fabricado por el Espejo de Northland!",
  ui_story_5087_50871102_76_dialog_content = "El Palacio de Invierno está demasiado limpio...",
  ui_story_5087_50871102_77_dialog_content = "¡Porque no hay sombras! ¡Todo aquí es una ilusión sin sombras creada por el espejo! ¡Incluso la reina es una ilusión!",
  ui_story_5087_50871102_78_dialog_content = "¡Es cierto! Las velas y los muebles no tienen sombras, ¡pero yo sí! Y Nepolis...",
  ui_story_5087_50871102_79_dialog_content = "... ¡Espera! ¡Estás equivocado! ¡Nepolis tiene una sombra! ¡Ella es real!",
  ui_story_5087_50871102_80_dialog_content = "... ¿Todavía no ha llegado Shaya? ¡Ella te explicará todo! En este punto, supongo que puedo decirte la verdad. Shaya es Beth—",
  ui_story_5087_50871102_81_dialog_content = "Ella no viene.",
  ui_story_5087_50871102_82_dialog_content = "Estás—",
  ui_story_5087_50871102_83_dialog_content = "<color=#e8d9bb>Nikinis mira instintivamente a los pies de la reina. No hay nada allí, ni tampoco hay algo cerca de los pies de los guardias reales.</color>",
  ui_story_5087_50871102_84_dialog_content = "<color=#e8d9bb>¡Nada! ¡No hay nada allí! ¡Ninguno de ellos tiene una sombra!</color>",
  ui_story_5087_50871102_85_dialog_content = "<color=#e8d9bb>La \"reina\" congela el Espejo de Northland con un movimiento de su palma, y con otro movimiento, el espejo sale volando y se hace añicos.</color>",
  ui_story_5087_50871102_86_dialog_content = "... ¡Así que eres un falso!",
  ui_story_5087_50871102_87_dialog_content = "No soy el único. Muéstrense, todos.",
  ui_story_5087_50871102_88_dialog_content = "¡Graaah!",
  ui_story_5087_50871102_89_dialog_content = "¡Ni siquiera lo pienses! No te dejaré lastimar a Nepolis—",
  ui_story_5087_50871102_90_dialog_content = "¿Nepolis? Je, verificaste mi sombra, ¿pero no estás haciendo lo mismo con ella?",
  ui_story_5087_50871102_91_dialog_content = "No... Ella es diferente...",
  ui_story_5087_50871102_92_dialog_content = "Graah! Graaah!",
  ui_story_5087_50871102_93_dialog_content = "¿Por qué inventaría las vidas de tus padres? ¡Porque solo viven en este mundo!",
  ui_story_5087_50871102_94_dialog_content = "Igual que Nepolis.",
  ui_story_5087_50871102_95_dialog_content = "¡No... Detente!",
  ui_story_5087_50871102_96_dialog_content = "... Dios, nos conocemos desde hace tanto tiempo. Pensé que eras más inteligente que esto.",
  ui_story_5087_50871102_97_dialog_content = "Bueno, te capturaré primero, luego te haré enfrentar la realidad lentamente.",
  ui_story_5087_50871102_98_dialog_content = "¡Consíguela! No importa si eres un poco brusco!",
  ui_story_5087_50871102_99_dialog_content = "¡Graaah!",
  ui_story_5087_50871102_100_dialog_content = "<color=#e8d9bb>¡Ugh! El golpe más fuerte no cae en Nikinis.</color>",
  ui_story_5087_50871102_101_dialog_content = "¿N-Nepolis?",
  ui_story_5087_50871102_102_dialog_content = "<color=#e8d9bb>Nikinis observa cómo algo oscuro e indistinto fluye de la herida de Nepolis—</color>",
  ui_story_5087_50871102_103_dialog_content = "<color=#e8d9bb>Y entonces, ella comienza a derretirse en el lugar.</color>",
  ui_story_5087_50871102_104_dialog_content = "No... Esto no es real... ¡Nepolis... Nepolis!",
  ui_story_5087_50871102_105_dialog_content = "N-Nikinis...",
  ui_story_5087_50871102_106_dialog_content = "Nepolis... ¡No! No... Por favor, no te vayas—",
  ui_story_5087_50871102_107_dialog_content = "¡R-Corre!",
  ui_story_5087_50871102_108_dialog_content = "!",
  ui_story_5087_50871102_109_dialog_content = "<color=#e8d9bb>Innumerables monstruos avanzan rápidamente y arrasan con la figura sombría de Nepolis.</color>",
  ui_story_5087_50871102_110_dialog_content = "¡NO! ¿Adónde has ido, Nepolis?",
  ui_story_5087_50871102_111_dialog_content = "<color=#e8d9bb>Nikinis agarra frenéticamente, pero todo lo que queda es una mera brizna de oscura niebla que se disipa en su agarre.</color>",
  ui_story_5087_50871102_112_dialog_content = "Nepolis... Nepolis...",
  ui_story_5087_50871102_113_dialog_content = "Graaaaah!",
  ui_story_5087_50871102_114_dialog_content = "...",
  ui_story_5087_50871102_115_dialog_content = "¡Todo es tu culpa! ¡Tú monstruos!",
  ui_story_5087_50871102_116_dialog_content = "Graah...",
  ui_story_5087_50871102_117_dialog_content = "¿Has recuperado una parte de tu poder de la realidad?",
  ui_story_5087_50871102_118_dialog_content = "Nepolis, ¿dónde estás? Por favor, no me asustes así... Oh, has ido adelante para abrirme un camino, ¿verdad? Vaya, deberías haberme dicho...",
  ui_story_5087_50871102_119_dialog_content = "¡Estoy en camino hacia ti!",
  ui_story_5087_50871102_120_dialog_content = "Nepolis—",
  ui_story_5087_50871102_121_dialog_content = "Népolis...",
  ui_story_5087_50871102_122_dialog_content = "Nepolis, ¿dónde estás? ¡Te lo ruego! Por favor, vuelve a mí...",
  ui_story_5087_50871102_123_dialog_content = "<color=#e8d9bb>Sin darse cuenta, Nikinis llega a la cabaña donde encontró el Espejo de Northland con Nepolis.</color>",
  ui_story_5087_50871102_124_dialog_content = "¿Nepolis, viniste aquí para esperarme?",
  ui_story_5087_50871102_125_dialog_content = "<color=#e8d9bb>Entre la abrumadora fragancia de las flores, las flores blancas puras hechas de Luminatics permanecen en plena floración dentro de la cabaña.</color>",
  ui_story_5087_50871102_126_dialog_content = "<color=#e8d9bb>Pero solo quedan narcisos blancos. Todos ellos son narcisos blancos.</color>",
  ui_story_5087_50871102_127_dialog_content = "<color=#e8d9bb>Todos los lirios se han ido, como si nunca hubieran estado allí, para empezar.</color>",
  ui_story_5087_50871102_128_dialog_content = "¿N-Nepolis?",
  ui_story_5087_50871102_129_dialog_content = "\"¿Puedes recordar esas hermosas flores blancas? Dos tallos creciendo en armonía junto al tranquilo lago.\"",
  ui_story_5087_50871102_130_dialog_content = "No, no, no...",
  ui_story_5087_50871102_131_dialog_content = "\"Bajo la caída de la nieve gris, el lirio prístino pronto fue enterrado.\"",
  ui_story_5087_50871102_132_dialog_content = "\"Dejado solo en el mundo, el narciso blanco lloró en silencio.\"",
  ui_story_5087_50871102_133_dialog_content = "... ¡Waaaaaaaaaaaaaaaaaaaah!",
  ui_story_5087_50871200_1_dialog_content = "Que extraño.",
  ui_story_5087_50871200_2_dialog_content = "Mamá y papá dijeron que se ha ido, pero Nepolis siempre ha estado a mi lado.",
  ui_story_5087_50871200_3_dialog_content = "<color=#e8d9bb>Zumbido... Las moscas aterrizan en algo de carne roja que está perdiendo gradualmente su forma.</color>",
  ui_story_5087_50871200_4_dialog_content = "Ese olor... ¡Ah! ¿Es ese el estofado de manzana de la semana pasada? ¿Qué hace allí, Nikinis?",
  ui_story_5087_50871200_5_dialog_content = "Aunque no quieras comerlo, ¡al menos tira las sobras! Solo mira eso...",
  ui_story_5087_50871200_6_dialog_content = "Pero... Esa es la parte de Nepolis.",
  ui_story_5087_50871200_7_dialog_content = "!",
  ui_story_5087_50871200_8_dialog_content = "Qué extraño. ¿Por qué Nepolis no lo comerá? El estofado de manzana es su favorito.",
  ui_story_5087_50871200_9_dialog_content = "¡Lo sé! ¡Debe estar teniendo poco apetito últimamente! Incluso habla menos ahora... ¿Es un efecto secundario de su enfermedad?",
  ui_story_5087_50871200_10_dialog_content = "¡Te encontré! Ahora, ¿quién es el siguiente?",
  ui_story_5087_50871200_11_dialog_content = "¡Oye! ¡Déjanos unirnos a ustedes!",
  ui_story_5087_50871200_12_dialog_content = "¿Eh? Pero estás solo.",
  ui_story_5087_50871200_13_dialog_content = "¿Qué quieres decir? ¡Mi hermana está justo a mi lado! Ha estado hablando menos últimamente, pero sé que quiere jugar con todos!",
  ui_story_5087_50871200_14_dialog_content = "Nuestra Luminatic está vinculada, así que sé todo lo que ella está pensando.",
  ui_story_5087_50871200_15_dialog_content = "... Está loca.",
  ui_story_5087_50871200_16_dialog_content = "Nikinis está loca! Se ha vuelto loca!",
  ui_story_5087_50871200_17_dialog_content = "¡Estás loco! ¡Estás enojado! Mi hermana solo está enferma, ¡y eso debilitó su Luminática! ¡Ella siempre está allí! ¡Puedo verla!",
  ui_story_5087_50871200_18_dialog_content = "Su Majestad, se lo suplico. Por favor, ayude a Nikinis! Desde Nepolis... ya sabe, ha estado así desde entonces...",
  ui_story_5087_50871200_19_dialog_content = "¡Los doctores están desconcertados! ¡Eres nuestra última esperanza! ¡Se lo ruego, Su Majestad!",
  ui_story_5087_50871200_20_dialog_content = "... La situación de tus hijas gemelas es un caso extremadamente raro.",
  ui_story_5087_50871200_21_dialog_content = "Tengo una idea, pero es demasiado peligrosa. Déjame pensarlo más.",
  ui_story_5087_50871200_22_dialog_content = "¿Tu nombre es Nikinis? Es un nombre hermoso. Dado que a tu hermana, Nepolis, no le gusta hablar, ¿podrías presentármela?",
  ui_story_5087_50871200_23_dialog_content = "¿Acabas de... preguntar sobre mi hermana? ¡Gracias a Dios! ¡Alguien finalmente me cree!",
  ui_story_5087_50871200_24_dialog_content = "¿Pero podrías tratarla primero? Está enferma, y aún no se ha recuperado completamente hasta ahora...",
  ui_story_5087_50871200_25_dialog_content = "Nuestras almas son una, así que tratarme solo a mí no funcionará... ¡Estaré bien una vez que ella esté bien!",
  ui_story_5087_50871200_26_dialog_content = "...",
  ui_story_5087_50871200_27_dialog_content = "¡Nepolis, Nepolis! ¡Su Majestad definitivamente podrá curarte! ¡Esto es una gran noticia!",
  ui_story_5087_50871200_28_dialog_content = "Sí... Yo también estoy muy emocionado...",
  ui_story_5087_50871200_29_dialog_content = "Entonces, ¿qué tal un juego de escondite? No todos los días podemos pasar la noche en el Palacio de Invierno. ¡Divirtámonos un poco!",
  ui_story_5087_50871200_30_dialog_content = "Este lugar se siente realmente misterioso... Nepolis, ¿tú también lo sientes?",
  ui_story_5087_50871200_31_dialog_content = "...",
  ui_story_5087_50871200_32_dialog_content = "Pequeño Aurorian... Pequeño Aurorian por allí...",
  ui_story_5087_50871200_33_dialog_content = "¿Eh? ¿Quién está ahí? ¿Con quién estás hablando? ¿Soy yo? ¿O mi hermana?",
  ui_story_5087_50871200_34_dialog_content = "Solo tú puedes ver a tu hermana y sentir su alma. Es solitario, ¿no es así, pequeño Aurorian...",
  ui_story_5087_50871200_35_dialog_content = "!",
  ui_story_5087_50871200_36_dialog_content = "Yo... puedo ayudarte. Acércate...",
  ui_story_5087_50871200_37_dialog_content = "... ¿Un espejo? ¿Cómo se supone que un espejo me va a ayudar?",
  ui_story_5087_50871200_38_dialog_content = "Pequeño Aurorian, no sabes nada sobre el poder del espejo.",
  ui_story_5087_50871200_39_dialog_content = "Puedo restaurar a tu hermana a su antigua gloria. Todos podrán verla y sentir su presencia—",
  ui_story_5087_50871200_40_dialog_content = "Pero debes hacer un pacto conmigo.",
  ui_story_5087_50871200_41_dialog_content = "¿E-Es eso cierto? ¿Jugará conmigo, bromeará conmigo y peleará conmigo, tal como solía hacer?",
  ui_story_5087_50871200_42_dialog_content = "¿Qué debo hacer?",
  ui_story_5087_50871200_43_dialog_content = "Dame tu... Lumina.",
  ui_story_5087_50871200_44_dialog_content = "¿Mi Lumina? ¿Así?",
  ui_story_5087_50871200_45_dialog_content = "<color=#e8d9bb>Su joven palma cubre el espejo—</color>",
  ui_story_5087_50871200_46_dialog_content = "¡La reliquia ha sido despertada! Está absorbiendo Lumina... ¡Notifique a Su Majestad inmediatamente!",
  ui_story_5087_50871200_47_dialog_content = "Ese niño, Nikinis... Todavía está inconsciente. El Espejo de Northland tomó demasiada Lumina de ella.",
  ui_story_5087_50871200_48_dialog_content = "¿Volverá a despertar alguna vez?",
  ui_story_5087_50871200_49_dialog_content = "El Espejo de Northland la ha elegido como su anfitriona. Sus posibilidades de supervivencia son escasas.",
  ui_story_5087_50871200_50_dialog_content = "... A menos que selle su cuerpo con el Espejo de Northland.",
  ui_story_5087_50871200_51_dialog_content = "Si puede adaptarse a la reliquia y recuperar la conciencia por sí misma, sobrevivirá. De lo contrario...",
  ui_story_5087_50871200_52_dialog_content = "Supongo que esa es la única solución...",
  ui_story_5087_50871200_53_dialog_content = "*suspiros* Esta es la situación exacta que intentabas evitar al no tratarla con el Espejo de Northland.",
  ui_story_5087_50871200_54_dialog_content = "Nunca podríamos haber sabido que el Espejo de Northland la seduciría... ¿Es ella tan compatible con él?",
  ui_story_5087_50871200_55_dialog_content = "No puedes llamar a eso \"tratamiento\". Es simplemente utilizar el poder del \"Espejo de Northland\" en el reino mental para—",
  ui_story_5087_50871200_56_dialog_content = "Elimina a la fuerza los restos de Luminatics dejados por su difunta hermana.",
  ui_story_5087_50871200_57_dialog_content = "Es bastante maravilloso que la Luminatics de una hermana permanezca dentro de la otra hermana.",
  ui_story_5087_50871200_58_dialog_content = "Nikinis y Nepolis son especiales. Su conexión es tan estrecha que es casi como una sola alma dividida en dos cuerpos.",
  ui_story_5087_50871200_59_dialog_content = "Es por eso que el tratamiento de Nikinis debe realizarse con extrema precaución. Si se eliminan a la fuerza los restos de su hermana—",
  ui_story_5087_50871200_60_dialog_content = "Aunque ciertamente no volverá a \"ver\" a su hermana, el tiempo que pasaron juntas, los recuerdos que compartieron, las percepciones que formaron juntas...",
  ui_story_5087_50871200_61_dialog_content = "Todo será arrojado al desorden o incluso desaparecerá.",
  ui_story_5087_50871200_62_dialog_content = "No será diferente a quitarle la mitad de ella.",
  ui_story_5087_50871200_63_dialog_content = "En efecto. Ese riesgo es imposible de eliminar, ni siquiera con la ayuda del espejo de Northland.",
  ui_story_5087_50871200_64_dialog_content = "Hermanas gemelas conectadas tanto en mente como en alma, pero la hermana mayor se enfermó...",
  ui_story_5087_50871200_65_dialog_content = "Y la muerte los separó... ¿Por qué el destino siempre nos juega estas trampas a todos?",
  ui_story_5087_50871200_66_dialog_content = "... Pero ¿están realmente separados?",
  ui_story_5087_50871200_67_dialog_content = "Novio, ¿crees que... el alma de un auroriano existe dentro de Luminatics?",
  ui_story_5087_50871300_1_dialog_content = "(Lo recuerdo ahora, todo.)",
  ui_story_5087_50871300_2_dialog_content = "(Nepolis falleció hace mucho tiempo, y Queen Bethlehem me selló en la cueva congelada para salvar mi vida.)",
  ui_story_5087_50871300_3_dialog_content = "(Ambos, mamá y papá, fallecieron durante este tiempo.)",
  ui_story_5087_50871300_4_dialog_content = "(No podía recordar vivir con mis padres después de recuperar la conciencia...)",
  ui_story_5087_50871300_5_dialog_content = "<color=#e8d9bb>Al abrir los ojos en la cueva congelada, la Auroriana conocida como Nikinis no tenía nada más.</color>",
  ui_story_5087_50871300_6_dialog_content = "<color=#e8d9bb>Sin hogar, ciudad natal o recuerdos. Estaba sola en el mundo con solo su frágil e incompleto ser.</color>",
  ui_story_5087_50871300_7_dialog_content = "<color=#e8d9bb>Además del suave resplandor del espejo mágico a su lado, lo único que la recibió fue—</color>",
  ui_story_5087_50871300_8_dialog_content = "<color=#e8d9bb>Una imagen sonriente de sí misma, saliendo de entre los lirios completamente florecidos reflejados en la superficie del espejo.</color>",
  ui_story_5087_50871300_9_dialog_content = "\"¿Qué estás mirando? ¿No reconoces a tu propia hermana?\"",
  ui_story_5087_50871300_10_dialog_content = "\"Mi Nikinis... Mi otra mitad...\"",
  ui_story_5087_50871300_11_dialog_content = "(Todo esto... Esta es mi realidad...)",
  ui_story_5087_50871300_12_dialog_content = "(Una realidad más cruel y terrible que el mundo espejo.)",
  ui_story_5087_50871300_13_dialog_content = "Entonces, ¿por qué no te quedas en el espejo?",
  ui_story_5087_50871300_14_dialog_content = "...",
  ui_story_5087_50871300_15_dialog_content = "Tú de nuevo... Todavía tienes el descaro de hablarme tan descaradamente...",
  ui_story_5087_50871300_16_dialog_content = "¡Todo es tu culpa!",
  ui_story_5087_50871300_17_dialog_content = "No seas tan crítico... Todo lo que hice fue cumplir tu deseo.",
  ui_story_5087_50871300_18_dialog_content = "Querías disfrutar la vida con tu hermana, y te lo di. Querías luchar a su lado, y también te lo di.",
  ui_story_5087_50871300_19_dialog_content = "Incluso los recuerdos de la realidad que buscabas recuperar, también te los di, incluso si eso no me beneficiaría de ninguna manera.",
  ui_story_5087_50871300_20_dialog_content = "Oh, desearía que mostraras algo de gratitud. Mi anfitrión y contratista...",
  ui_story_5087_50871300_21_dialog_content = "¡Recuperé mis propios recuerdos! ¡Ni siquiera pienses en tomar crédito por eso!",
  ui_story_5087_50871300_22_dialog_content = "¿Cómo se sintió al recuperar esos recuerdos? ¿Lo disfrutaste?",
  ui_story_5087_50871300_23_dialog_content = "...",
  ui_story_5087_50871300_24_dialog_content = "No fue divertido, ¿verdad? La oscuridad y el aburrimiento de la vida real es algo que yo, el creador de ilusiones, conozco mejor que nadie.",
  ui_story_5087_50871300_25_dialog_content = "Entonces, quédate dentro del espejo.",
  ui_story_5087_50871300_26_dialog_content = "Puedo cumplir cada uno de tus deseos.",
  ui_story_5087_50871300_27_dialog_content = "Cualquier cosa que pueda ser reflejada por el espejo es un regalo de mí para ti.",
  ui_story_5087_50871300_28_dialog_content = "¡Todo lo que se necesita es un pensamiento para que te conviertas en el gobernante del mundo espejo! ¡Todo el mundo estará a tus pies!",
  ui_story_5087_50871300_29_dialog_content = "¿O tu codicia no es tan grande? Tal vez lo que deseas es simplemente—",
  ui_story_5087_50871300_30_dialog_content = "Nikinis, no quiero perderte de nuevo...",
  ui_story_5087_50871300_31_dialog_content = "¡Nepolis!",
  ui_story_5087_50871300_32_dialog_content = "Quédate conmigo. Cumplirás este pequeño deseo mío, ¿no es así?",
  ui_story_5087_50871300_33_dialog_content = "(Yo...)",
  ui_story_5087_50871300_34_dialog_content = "Si te quedas dentro del espejo, puedo tomar tu lugar <color=#FFB400>en la realidad</color>.",
  ui_story_5087_50871300_35_dialog_content = "Los lirios volverán a florecer en Northland... e incluso en todas las tierras de Astra.",
  ui_story_5087_50871300_36_dialog_content = "... ¿En serio? ¿Es ese tu deseo?",
  ui_story_5087_50871300_37_dialog_content = "Si.",
  ui_story_5087_50871300_38_dialog_content = "Bueno, en ese caso...",
  ui_story_5087_50871300_39_dialog_content = "Lo haré.",
  ui_story_5087_50871400_1_dialog_content = "No puedo creer que este bosque, las llanuras nevadas, la escarcha y todo sea parte de la ilusión del espejo.",
  ui_story_5087_50871400_2_dialog_content = "¡No es diferente de la realidad!",
  ui_story_5087_50871400_3_dialog_content = "Nikinis... Nikinis...",
  ui_story_5087_50871400_4_dialog_content = "El mundo espejo no está tan mal, o más bien, no hay nada malo en él en absoluto.",
  ui_story_5087_50871400_5_dialog_content = "Nikinis—",
  ui_story_5087_50871400_6_dialog_content = "Nepolis y mis padres, todos están conmigo de nuevo...",
  ui_story_5087_50871400_7_dialog_content = "¡Nikinis!",
  ui_story_5087_50871400_8_dialog_content = "!",
  ui_story_5087_50871400_9_dialog_content = "<color=#e8d9bb>La fuerte nevada continuó durante varios días, y el hielo y la nieve en todo Northland se volvieron cada vez más cristalinos. Un cristal de hielo revolotea con el viento y aterriza en la palma de Nikinis.</color>",
  ui_story_5087_50871400_10_dialog_content = "<color=#e8d9bb>Una figura familiar aparece en la superficie del cristal de hielo.</color>",
  ui_story_5087_50871400_11_dialog_content = "¡El del espejo!",
  ui_story_5087_50871400_12_dialog_content = "No... Ahora recuerdo. Tú eres... PlayerName.",
  ui_story_5087_50871400_13_dialog_content = "Encontraste este lugar... ¿Pasaste por todos estos problemas solo para traerme de vuelta a la realidad?",
  ui_story_5087_50871400_14_dialog_content = "¿Tú recuerdas todo? ¡Qué alivio! Ahora escucha, debemos—",
  ui_story_5087_50871400_15_dialog_content = "... Eso es suficiente.",
  ui_story_5087_50871400_16_dialog_content = "¿Ah?",
  ui_story_5087_50871400_17_dialog_content = "Aprecio lo que has hecho. Durante mi tiempo viviendo en la realidad, nunca esperé que alguien fuera tan lejos por mí.",
  ui_story_5087_50871400_18_dialog_content = "Pero está bien ahora. Descansa un poco. Ya no tienes que perder tiempo buscándome.",
  ui_story_5087_50871400_19_dialog_content = "Tengo la intención de quedarme dentro del espejo.",
  ui_story_5087_50871400_20_dialog_content = "... ¿Es por tu hermana?",
  ui_story_5087_50871400_21_dialog_content = "Mi \"hermana\"... En efecto.",
  ui_story_5087_50871400_22_dialog_content = "Aunque ella es simplemente una ilusión creada por el Espejo de Northland al extraer los restos de su Luminatics de dentro de mí...",
  ui_story_5087_50871400_23_dialog_content = "Ella sigue siendo la misma hermana que conocía.",
  ui_story_5087_50871400_24_dialog_content = "Ella desea vivir en la realidad nuevamente, y los lirios desean florecer por todo Northland...",
  ui_story_5087_50871400_25_dialog_content = "¿Cómo podría negar su único deseo?",
  ui_story_5087_50871400_26_dialog_content = "¿Es eso realmente lo que quiere Nepolis? ¡Es probable que el espejo mágico esté haciendo uso de su imagen nuevamente para que te quedes!",
  ui_story_5087_50871400_27_dialog_content = "¡Justo como lo hizo en la Sala de Reliquias! Quiere que te quedes en el espejo para que pueda tomar el control total de tu cuerpo—",
  ui_story_5087_50871400_28_dialog_content = "Eso todavía no cambiará mi decisión.",
  ui_story_5087_50871400_29_dialog_content = "?",
  ui_story_5087_50871400_30_dialog_content = "Si la conciencia de Nepolis permanece, y ella desea regresar a la realidad con la ayuda del espejo...",
  ui_story_5087_50871400_31_dialog_content = "Entonces no puedo ir en contra de sus deseos y apagar su esperanza de vivir.",
  ui_story_5087_50871400_32_dialog_content = "Si Nepolis ha sido devorada por el espejo, y solo queda una ilusión de ella...",
  ui_story_5087_50871400_33_dialog_content = "Demuestra que el Espejo de Northland ha tomado completamente la mitad de mi alma.",
  ui_story_5087_50871400_34_dialog_content = "Si regreso a la realidad en ese estado, incluso yo no puedo predecir qué tipo de cosas terribles podría ser manipulado para hacer.",
  ui_story_5087_50871400_35_dialog_content = "... Es probable que incluso te lastime.",
  ui_story_5087_50871400_36_dialog_content = "¡Ahora no es el momento de preocuparte por mí!",
  ui_story_5087_50871400_37_dialog_content = "¡No tengo derecho a ignorar tu bienestar cuando te niegas a abandonarme!",
  ui_story_5087_50871400_38_dialog_content = "¡Escúchame! No creo que Nepolis—",
  ui_story_5087_50871400_39_dialog_content = "PlayerName, dile a Su Majestad que me vuelva a sellar.",
  ui_story_5087_50871400_40_dialog_content = "Es la única manera en que puedo proteger tanto a Nepolis como a ti—",
  ui_story_5087_50871400_41_dialog_content = "¡NO! ¡Sólo escúchame!",
  ui_story_5087_50871400_42_dialog_content = "Qué...",
  ui_story_5087_50871400_43_dialog_content = "¡Hay una tercera posibilidad!",
  ui_story_5087_50871400_44_dialog_content = "Una tercera... ¿posibilidad?",
  ui_story_5087_50871400_45_dialog_content = "Según tú, Nepolis eligió voluntariamente el Espejo de Northland, o el espejo la devoró hace mucho tiempo...",
  ui_story_5087_50871400_46_dialog_content = "¡Pero esas no son las únicas posibilidades!",
  ui_story_5087_50871400_47_dialog_content = "¿Y si su conciencia permanece, y... ella todavía está resistiendo el espejo?",
  ui_story_5087_50871400_48_dialog_content = "Ella había caído bajo el control del espejo en la Sala de Reliquias...",
  ui_story_5087_50871400_49_dialog_content = "... Pero, ¿no recuperó su conciencia en el último momento y te salvó?",
  ui_story_5087_50871400_50_dialog_content = "!",
  ui_story_5087_50871400_51_dialog_content = "N-Nikinis...",
  ui_story_5087_50871400_52_dialog_content = "¡R-Corre!",
  ui_story_5087_50871400_53_dialog_content = "¡Ver que escapas del control del espejo y vives una buena vida es lo que Nepolis <color=#FFB400>realmente desea</color>!",
  ui_story_5087_50871400_54_dialog_content = "Nepolis... ¿Su verdadero deseo? ¿No quiere que me quede en el espejo? ¿No quiere que me quede a su lado?",
  ui_story_5087_50871400_55_dialog_content = "... Por supuesto que ella quiere estar contigo.",
  ui_story_5087_50871400_56_dialog_content = "¡Pero ella preferiría verte extender tus alas, volar alto y convertirte en un alma libre e independiente!",
  ui_story_5087_50871400_57_dialog_content = "Me niego a despojarte de tus alas.",
  ui_story_5087_50871400_58_dialog_content = "Hazlo, Nikinis.",
  ui_story_5087_50871400_59_dialog_content = "Debes recuperar tus recuerdos, descifrar todo y volver para contarme cada detalle.",
  ui_story_5087_50871400_60_dialog_content = "Entonces, solo hazlo. Es una promesa.",
  ui_story_5087_50871400_61_dialog_content = "¿Por qué... Nepolis? ¿D-De verdad todavía estás a mi lado?",
  ui_story_5087_50871400_62_dialog_content = "Incluso después de perder su forma física, ella aún permanece y desea protegerte.",
  ui_story_5087_50871400_63_dialog_content = "Regresa, Nikinis! Solo vuelve a la realidad. Puedes dejar el espejo y a Nepolis a Shaya.",
  ui_story_5087_50871400_64_dialog_content = "¡Estoy seguro de que ella encontrará una manera!",
  ui_story_5087_50871400_65_dialog_content = "Shaya... Rosas amarillas y no-me-olvides... ¡Ah! No me digas—",
  ui_story_5087_50871400_66_dialog_content = "Oh, y hay otra cosa que tienes mal.",
  ui_story_5087_50871400_67_dialog_content = "Nunca he sido el único que haría todo lo posible por ti.",
  ui_story_5087_50871400_68_dialog_content = "Su Majestad, siempre he querido presentarle estas flores ya que simbolizan—",
  ui_story_5087_50871400_69_dialog_content = "Una amistad apreciada, ¿verdad?",
  ui_story_5087_50871400_70_dialog_content = "Has estado deambulando por los jardines durante tantos días que comencé a preguntarme cuándo finalmente estarías dispuesto a darme esas flores.",
  ui_story_5087_50871400_71_dialog_content = "Shaya es la verdadera Queen Bethlehem.",
  ui_story_5087_50871400_72_dialog_content = "¡Ella entró al mundo espejo para traerte de vuelta!",
  ui_story_5087_50871501_1_dialog_content = "¡Su Majestad ha declarado a Nikinis cómplice del robo en el Palacio de Invierno! ¡Actualmente está en fuga! ¡Esconderla o ayudarla es un delito!",
  ui_story_5087_50871501_2_dialog_content = "Los ladrones usarán espejos para causar estragos. ¡Habitantes de Northland!",
  ui_story_5087_50871501_3_dialog_content = "¡Destruye todos los espejos inmediatamente! ¡Cualquier cosa que pueda reflejar la imagen de una persona debe ser destruida!",
  ui_story_5087_50871501_4_dialog_content = "Graah!",
  ui_story_5087_50871501_5_dialog_content = "Graah...",
  ui_story_5087_50871501_6_dialog_content = "¿Cómo es la situación, Nikinis? Urgh, estos monstruos simplemente no se rendirán...",
  ui_story_5087_50871501_7_dialog_content = "No está tan mal. ¿Cuál es mi próximo movimiento?",
  ui_story_5087_50871501_8_dialog_content = "... Dame un momento para pensar. El espejo de Northland ha notado mis intenciones y está intentando destruir todas las salidas...",
  ui_story_5087_50871501_9_dialog_content = "¿La orden de destruir todos los espejos?",
  ui_story_5087_50871501_10_dialog_content = "Así es. Los espejos son pasajes a la realidad. La estabilidad y conectividad de un pasaje es proporcional al área de superficie y reflectancia del espejo.",
  ui_story_5087_50871501_11_dialog_content = "Este pequeño cristal de hielo es capaz de facilitar la comunicación entre nosotros como máximo. No es suficiente para traerte de vuelta a la realidad.",
  ui_story_5087_50871501_12_dialog_content = "¿Así que necesito un espejo grande y suave?",
  ui_story_5087_50871501_13_dialog_content = "Exactamente. El Espejo de Northland en sí es el mejor pasadizo. Shaya entró a este mundo a través de él y lo robó...",
  ui_story_5087_50871501_14_dialog_content = "El plan era asegurar nuestro pasaje antes de convencerte de volver a la realidad.",
  ui_story_5087_50871501_15_dialog_content = "Desafortunadamente, la falsa reina estaba un paso adelante de nosotros y ordenó a los monstruos que habitaban en el Espejo de Northland destruirlo...",
  ui_story_5087_50871501_16_dialog_content = "... ¿Ella destruyó el espejo? ¡Y hasta hizo un acto para hacer que mi hermana y yo lo buscáramos!",
  ui_story_5087_50871501_17_dialog_content = "PlayerName, conoces el Palacio de Invierno como la palma de tu mano—",
  ui_story_5087_50871501_18_dialog_content = "¿Existe una forma de colarse nuevamente en la Sala de Reliquias y llegar al Espejo de Northland?",
  ui_story_5087_50871501_19_dialog_content = "Temo que la Sala de Reliquias es probablemente el lugar más fuertemente custodiado en Northland...",
  ui_story_5087_50871501_20_dialog_content = "Entonces deberíamos olvidarnos del Espejo de Northland y centrarnos en encontrar otro camino.",
  ui_story_5087_50871501_21_dialog_content = "Ahora que la falsa reina ha ordenado la destrucción de todos los espejos, asegurar otro pasadizo no será fácil en absoluto... ¡Pero tienes razón! ¡No hay otra manera!",
  ui_story_5087_50871501_22_dialog_content = "Estás inesperadamente tranquilo, Nikinis. Siento como si estuviera mirando de nuevo tu figura impresionante e indomable en el campo de batalla.",
  ui_story_5087_50871501_23_dialog_content = "... Porque Nepolis se ha idado.",
  ui_story_5087_50871501_24_dialog_content = "En ese entonces, no tenía a nadie en quien confiar o que me mimara.",
  ui_story_5087_50871501_25_dialog_content = "Nikinis...",
  ui_story_5087_50871501_26_dialog_content = "Elegiste tomar el camino sin tu hermana.",
  ui_story_5087_50871501_27_dialog_content = "!",
  ui_story_5087_50871501_28_dialog_content = "<color=#e8d9bb>La nieve se desplaza con el viento, como amenazantes soldados silbando a través del viento mientras responden al llamado de los tambores de batalla—</color>",
  ui_story_5087_50871501_29_dialog_content = "<color=#e8d9bb>Acompañando a la figura que se acerca a pie y haciendo una reverencia ante su mirada helada.</color>",
  ui_story_5087_50871501_30_dialog_content = "¡Es la \"reina\"! Entre todas las reflexiones del espejo de Northland...",
  ui_story_5087_50871501_31_dialog_content = "... Ella es la más fuerte.",
  ui_story_5087_50871501_32_dialog_content = "Dado que eres consciente de eso, simplemente ríndete, Nikinis.",
  ui_story_5087_50871501_33_dialog_content = "Una vida tranquila y acogedora con tus padres y hermana. Solo di la palabra y es tuya.",
  ui_story_5087_50871501_34_dialog_content = "... Pero debo acostarme en la nieve oscura y olvidar mis alas.",
  ui_story_5087_50871501_35_dialog_content = "¿De verdad quieres esas alas parcialmente destruidas?",
  ui_story_5087_50871501_36_dialog_content = "Solo te traerán dolor. Cada aleteo infructuoso de esas alas es un recordatorio—",
  ui_story_5087_50871501_37_dialog_content = "Me recuerda que Nepolis estuvo aquí una vez.",
  ui_story_5087_50871501_38_dialog_content = "!",
  ui_story_5087_50871501_39_dialog_content = "Me recuerda la alegría y la libertad que compartimos mientras volábamos juntos.",
  ui_story_5087_50871501_40_dialog_content = "Nepolis se decepcionaría si abandonara esos recuerdos.",
  ui_story_5087_50871501_41_dialog_content = "Nunca decepcionaré a mi hermana.",
  ui_story_5087_50871501_42_dialog_content = "... Si esa es tu decisión—",
  ui_story_5087_50871501_43_dialog_content = "Nikinis! ¡Cuidado!",
  ui_story_5087_50871501_44_dialog_content = "¡Urgh!",
  ui_story_5087_50871501_45_dialog_content = "<color=#e8d9bb>La nieve levanta una sombra que parece casi congelar el mundo a su alrededor.</color>",
  ui_story_5087_50871501_46_dialog_content = "<color=#e8d9bb>La fuerza de la \"reina\" está muy por encima de la mayoría de los aurorianos.</color>",
  ui_story_5087_50871501_47_dialog_content = "<color=#e8d9bb>Nikinis lo da todo, pero apenas puede defenderse a sí misma y al pequeño cristal de hielo en su mano.</color>",
  ui_story_5087_50871501_48_dialog_content = "¿Ese frágil cristal de hielo es tu último espejo? Qué lástima.",
  ui_story_5087_50871501_49_dialog_content = "¡Cada copo de nieve en Northland... es un súbdito mío!",
  ui_story_5087_50871501_50_dialog_content = "... No te dejaré... tomar mi espejo! ¡Aaaah!",
  ui_story_5087_50871501_51_dialog_content = "Espejo... ¡Espera un minuto! ¡Todavía tenemos un espejo más! ¿Cómo pude haber olvidado?",
  ui_story_5087_50871501_52_dialog_content = "Bueno, no es demasiado tarde.",
  ui_story_5087_50871501_53_dialog_content = "!",
  ui_story_5087_50871501_54_dialog_content = "¿Shaya? No, tú eres...",
  ui_story_5087_50871501_55_dialog_content = "Ambos lo hicieron bien, PlayerName y Nikinis.",
  ui_story_5087_50871501_56_dialog_content = "Y tú... Creo que una estimación está en orden.",
  ui_story_5087_50871501_57_dialog_content = "...",
  ui_story_5087_50871501_58_dialog_content = "¡Baila para mí! ¡La nieve de Northland!",
  ui_story_5087_50871502_1_dialog_content = "<color=#e8d9bb>La nieve plateada cruza majestuosamente el aire y detiene la furiosa nieve oscura que se acerca.</color>",
  ui_story_5087_50871502_2_dialog_content = "Fuera de mi camino.",
  ui_story_5087_50871502_3_dialog_content = "¡Deja de intentar ser el héroe cuando solo eres un perro callejero que tiene que colarse en el Palacio de Invierno!",
  ui_story_5087_50871502_4_dialog_content = "¡Tú no eres la reina aquí!",
  ui_story_5087_50871502_5_dialog_content = "... No sabes nada sobre gobernar.",
  ui_story_5087_50871502_6_dialog_content = "La nieve de Northland no necesita un soberano. Tampoco los habitantes de Northland que coexisten con la nieve requieren grilletes innecesarios.",
  ui_story_5087_50871502_7_dialog_content = "La única razón de la existencia del soberano es heredar el poder para proteger a Northland.",
  ui_story_5087_50871502_8_dialog_content = "Puede que sea la reina, pero ante todo soy una guerrera de Northland—",
  ui_story_5087_50871502_9_dialog_content = "¿Crees que simplemente te dejaré poner tus manos en mis amigos? ¿Por qué no intentas atravesar mi ventisca primero?",
  ui_story_5087_50871502_10_dialog_content = "(Su Majestad...)",
  ui_story_5087_50871502_11_dialog_content = "¡Que ridículo!",
  ui_story_5087_50871502_12_dialog_content = "¡Nadie es mi igual en el mundo del espejo!",
  ui_story_5087_50871502_13_dialog_content = "Su Majestad, déjame ayudarte! ¡Urgh! Oh no—",
  ui_story_5087_50871502_14_dialog_content = "<color=#e8d9bb>Los vientos plateados y la nieve oscura chocan como behemots que podrían volcar el mundo.</color>",
  ui_story_5087_50871502_15_dialog_content = "<color=#e8d9bb>En un momento de descuido, el pequeño cristal de hielo se escapa del agarre de Nikinis y es arrastrado por la tormenta.</color>",
  ui_story_5087_50871502_16_dialog_content = "¡PlayerName!",
  ui_story_5087_50871502_17_dialog_content = "¡No te preocupes por mí! ¡Apresúrate a <color=#FFB400>Lago Espejo</color>!",
  ui_story_5087_50871502_18_dialog_content = "Lago Espejo... ¡Ese es tu hogar! Y es tu... último pasadizo...",
  ui_story_5087_50871502_19_dialog_content = "¡Es el espejo más grande, brillante y estable de Northland, así como el más familiar para ti!",
  ui_story_5087_50871502_20_dialog_content = "<color=#e8d9bb>El cristal de hielo es tragado por la tormenta, y la voz del Celestita ya no se escucha más.</color>",
  ui_story_5087_50871502_21_dialog_content = "<color=#e8d9bb>Solo queda el silbido de los vientos nevados alrededor de Nikinis.</color>",
  ui_story_5087_50871502_22_dialog_content = "<color=#e8d9bb>Aquellos que harían todo lo que esté a su alcance por ella, aún están luchando por ella en este mismo momento, y esa es la evidencia.</color>",
  ui_story_5087_50871502_23_dialog_content = "Gracias, Shaya... Queen Bethlehem...",
  ui_story_5087_50871502_24_dialog_content = "¡No te decepcionaré!",
  ui_story_5087_50871601_1_dialog_content = "<color=#e8d9bb>El mundo puede cambiar, y las tormentas pueden enfurecer, pero el Lago Espejo permanece inalterado.</color>",
  ui_story_5087_50871601_2_dialog_content = "<color=#e8d9bb>Descansa allí tranquilamente entre las montañas, claro como un espejo, y siempre igual.</color>",
  ui_story_5087_50871601_3_dialog_content = "<color=#e8d9bb>Concede una brisa refrescante, aire pacífico y suave fragancia floral a la figura apuesta de Nikinis.</color>",
  ui_story_5087_50871601_4_dialog_content = "<color=#e8d9bb>La fragancia tenue pero rica de flores blancas puras.</color>",
  ui_story_5087_50871601_5_dialog_content = "(El campo de flores junto al Lago Espejo... Hace solo unos días, estaba disfrutando de la vista aquí con Nepolis...)",
  ui_story_5087_50871601_6_dialog_content = "<color=#e8d9bb>Nikinis acaricia suavemente las flores blancas. Narcisos y lirios crecen en armonía junto al tranquilo lago.</color>",
  ui_story_5087_50871601_7_dialog_content = "<color=#e8d9bb>Una escena pintoresca que nunca deja de hacer palpitar su corazón. Ella nunca deja de intentar descubrir su significado.</color>",
  ui_story_5087_50871601_8_dialog_content = "Intentémoslo de nuevo, PlayerName. Preferiría no estar condenado a una vida de estar a la deriva, arrogante, aburrido y sin recuerdos...",
  ui_story_5087_50871601_9_dialog_content = "Y ni siquiera conociendo la razón de mi infelicidad.",
  ui_story_5087_50871601_10_dialog_content = "Estoy empezando a recordar cosas... ¡Por favor, ayúdame de nuevo con tus habilidades psíquicas!",
  ui_story_5087_50871601_11_dialog_content = "Está bien... Pero no te exijas. Vamos a parar si sientes alguna molestia, ¿de acuerdo?",
  ui_story_5087_50871601_12_dialog_content = "\"¿Puedes recordar...\"",
  ui_story_5087_50871601_13_dialog_content = "!",
  ui_story_5087_50871601_14_dialog_content = "<color=#e8d9bb>Un alegre fuego arde en la chimenea, su cálida luz crea sombras danzantes dentro de la pequeña cabaña.</color>",
  ui_story_5087_50871601_15_dialog_content = "<color=#e8d9bb>En el resplandor del fuego, se pueden ver cuatro figuras: un esposo y esposa, así como sus hijas gemelas que parecen imágenes de espejo una de la otra.</color>",
  ui_story_5087_50871601_16_dialog_content = "\"¿Puedes recordar esas hermosas flores blancas? Un par creciendo en armonía junto al tranquilo lago.\"",
  ui_story_5087_50871601_17_dialog_content = "...",
  ui_story_5087_50871601_18_dialog_content = "\"PlayerName, ahora lo recuerdo.\"",
  ui_story_5087_50871601_19_dialog_content = "\"Es solo un breve recuerdo de nuestros padres contándonos una historia.\"",
  ui_story_5087_50871601_20_dialog_content = "\"Pero estoy seguro de que esta misma memoria está ocultando la verdad detrás de mis recuerdos perdidos...\"",
  ui_story_5087_50871601_21_dialog_content = "\"¿Por qué no recuerdo vivir con mis padres?\"",
  ui_story_5087_50871601_22_dialog_content = "\"¿Por qué Nepolis está confinada a vivir dentro del espejo?\"",
  ui_story_5087_50871601_23_dialog_content = "\"¿Por qué siempre estoy infeliz como si hubiera un abismo sin fondo en mi corazón?\"",
  ui_story_5087_50871601_24_dialog_content = "\"Las respuestas que busco están definitivamente ocultas dentro del espejo mágico que nunca ha dejado mi lado...\"",
  ui_story_5087_50871601_25_dialog_content = "\"Entonces, me dirijo hacia el espejo. Nepolis está allí, y finalmente voy a su lado.\"",
  ui_story_5087_50871601_26_dialog_content = "\"Gracias, PlayerName.\"",
  ui_story_5087_50871601_27_dialog_content = "Eso es todo por mi mensaje.",
  ui_story_5087_50871601_28_dialog_content = "<color=#e8d9bb>El espejo espera adelante con un brillo suave y gentil, justo como el día en que Nikinis despertó en la cueva congelada.</color>",
  ui_story_5087_50871601_29_dialog_content = "<color=#e8d9bb>Nikinis toma una respiración profunda y avanza hacia su imagen en el espejo...</color>",
  ui_story_5087_50871601_30_dialog_content = "(Eso es cómo entré en el mundo del espejo y desperté en este campo de flores...)",
  ui_story_5087_50871601_31_dialog_content = "(Caminé de la mano con mi hermana y me deleité en la alegría despreocupada que este lugar tenía para ofrecer.)",
  ui_story_5087_50871601_32_dialog_content = "(Si tan solo pudiera sumergirme en este sueño... Pero—)",
  ui_story_5087_50871601_33_dialog_content = "Nikinis, he traído nuevos bulbos de lirio para ti. ¡Podemos plantarlos en el espacio vacío allí!",
  ui_story_5087_50871601_34_dialog_content = "¡Guau! La belleza del campo de flores de Nikinis nunca deja de crecer! Traeré algunas semillas la próxima vez.",
  ui_story_5087_50871601_35_dialog_content = "(El campo de flores es tan exuberante y hermoso gracias a la ayuda de numerosos habitantes de Northland.)",
  ui_story_5087_50871601_36_dialog_content = "Nikinis, ¡Ayudaré a arar la tierra! ¡Ho! Realmente está congelada sólida.",
  ui_story_5087_50871601_37_dialog_content = "¡Ayudaré con el riego!",
  ui_story_5087_50871601_38_dialog_content = "(Es el agua de la nieve derretida de Northland lo que permite que los delicados narcisos broten y florezcan.)",
  ui_story_5087_50871601_39_dialog_content = "Este sueño... Es hora de despertar.",
  ui_story_5087_50871601_40_dialog_content = "¿Por qué? ¿Has olvidado el final de la historia?",
  ui_story_5087_50871601_41_dialog_content = "El final...",
  ui_story_5087_50871601_42_dialog_content = "\"Desde ese día, una flor de lirio brotó del narciso, y ambos vivieron felices para siempre.\"",
  ui_story_5087_50871601_43_dialog_content = "¿Cómo pudiste pensar en abandonarme de nuevo después de prometerme un final así?",
  ui_story_5087_50871601_44_dialog_content = "¡Nikinis!",
  ui_story_5087_50871601_45_dialog_content = "¡No, eso no es! Yo—",
  ui_story_5087_50871601_46_dialog_content = "<color=#e8d9bb>Nikinis está a punto de defenderse cuando se queda en silencio al ver a su \"hermana\".</color>",
  ui_story_5087_50871601_47_dialog_content = "No eres mi hermana... Eres el espejo...",
  ui_story_5087_50871601_48_dialog_content = "Después de todo, Nepolis perdió contra ti...",
  ui_story_5087_50871601_49_dialog_content = "¿Perder? ¿Ganar? Todo es tu imaginación, Nikinis.",
  ui_story_5087_50871601_50_dialog_content = "Soy tu hermana, y ella soy yo. ¡La única opción que tienes es creer!",
  ui_story_5087_50871601_51_dialog_content = "De lo contrario, ¿no te dejaría sin más opción que pelear conmigo?",
  ui_story_5087_50871601_52_dialog_content = "Yo—",
  ui_story_5087_50871601_53_dialog_content = "Detenerme, aplastarme, pisotear mis deseos y destruir mi esperanza de sobrevivir... ¿Realmente eres capaz de todo eso?",
  ui_story_5087_50871601_54_dialog_content = "No puedes, ¿verdad? Porque eres Nikinis, el narciso que ama el lirio...",
  ui_story_5087_50871601_55_dialog_content = "No, yo... Tú no eres...",
  ui_story_5087_50871601_56_dialog_content = "Ahora, regresa a mi lado. Permíteme reemplazarte y buscar la libertad... Urgh—",
  ui_story_5087_50871601_57_dialog_content = "¡Urgh... Aaaaahhh!",
  ui_story_5087_50871601_58_dialog_content = "... Nikinis...",
  ui_story_5087_50871601_59_dialog_content = "¿Nepolis?",
  ui_story_5087_50871601_60_dialog_content = "¿Nepolis, eres tú? ¿Todavía estás aquí? Realmente eres... No es mi imaginación. No perdiste contra eso—",
  ui_story_5087_50871601_61_dialog_content = "... El final... de la historia...",
  ui_story_5087_50871601_62_dialog_content = "¿El final? Ya veo. Entonces, ¿deseas vivir de nuevo, verdad?",
  ui_story_5087_50871601_63_dialog_content = "Por supuesto, es justo que vivas y tomes mi lugar en la realidad—",
  ui_story_5087_50871601_64_dialog_content = "No...",
  ui_story_5087_50871601_65_dialog_content = "?",
  ui_story_5087_50871601_66_dialog_content = "\"Aunque el lirio regresó, su pureza se perdió. Se convirtió en una flor negra manchada de negro por la nieve contaminada.\"",
  ui_story_5087_50871601_67_dialog_content = "Eso es... el verdadero final...",
  ui_story_5087_50871601_68_dialog_content = "Nepolis, ¿qué estás diciendo?",
  ui_story_5087_50871601_69_dialog_content = "El espejo mágico y yo somos inseparables ahora, y ya no soy quien era. Es hora... de que me vaya.",
  ui_story_5087_50871601_70_dialog_content = "Pero es diferente para ti.",
  ui_story_5087_50871601_71_dialog_content = "¡No quiero escuchar una palabra más! Nepolis... Todo estará bien...",
  ui_story_5087_50871601_72_dialog_content = "Nikinis, mi querida hermana, no se acostará en la oscura nieve.",
  ui_story_5087_50871601_73_dialog_content = "Ella cruzará la nieve y superará el sufrimiento provocado por el destino...",
  ui_story_5087_50871601_74_dialog_content = "Ella irá más allá de la protección de su hermana para ver el mundo y amar a más personas...",
  ui_story_5087_50871601_75_dialog_content = "Ella crecerá digna y fuerte para proteger el legado, las fábulas y los poemas de Northland, y extenderá la bendición de las flores a tierras lejanas...",
  ui_story_5087_50871601_76_dialog_content = "¡Ella recogerá lo que se olvidó, recuperará lo que se perdió y escribirá un final a nuestro poema para que pueda nacer una nueva oda!",
  ui_story_5087_50871601_77_dialog_content = "Entonces, pelea.",
  ui_story_5087_50871601_78_dialog_content = "!",
  ui_story_5087_50871601_79_dialog_content = "¡Aplástame, destrúyeme y acaba conmigo, para que el espejo mágico no tenga nada en qué confiar!",
  ui_story_5087_50871601_80_dialog_content = "Permíteme devolverte el futuro que mereces, para que puedas volar alto con tus alas—",
  ui_story_5087_50871601_81_dialog_content = "Creo en ti.",
  ui_story_5087_50871601_82_dialog_content = "Népolis...",
  ui_story_5087_50871601_83_dialog_content = "¡Urgh... Urgh... ¡Aaaah!",
  ui_story_5087_50871601_84_dialog_content = "Jeje... Al final, todavía te niegas obstinadamente a aceptar el único camino hacia la felicidad, ¿eh? Mi hermana...",
  ui_story_5087_50871601_85_dialog_content = "¡NEPOLIS! ¡Aahhhh!",
  ui_story_5087_50871602_1_dialog_content = "<color=#e8d9bb>El reflejo verde oscuro de la Aurora serpentea a través de las aguas del Lago Espejo como una serpiente deslizándose bajo su superficie.</color>",
  ui_story_5087_50871602_2_dialog_content = "<color=#e8d9bb>Los gritos y choques de la batalla se han desvanecido. Claro como un espejo, y siempre igual, eternamente el Lago Espejo.</color>",
  ui_story_5087_50871602_3_dialog_content = "...",
  ui_story_5087_50871602_4_dialog_content = "<color=#e8d9bb>\"Estaré allí cuando me necesites...\"</color>",
  ui_story_5087_50871602_5_dialog_content = "<color=#e8d9bb>Las últimas palabras de Nepolis permanecen resonando en los oídos de Nikinis.</color>",
  ui_story_5087_50871602_6_dialog_content = "<color=#e8d9bb>Ella se queda allí en silencio entre los pétalos blancos puros desgarrados y revoloteando.</color>",
  ui_story_5087_50871602_7_dialog_content = "<color=#e8d9bb>El embriagador aroma floral llena el aire.</color>",
  ui_story_5087_50871602_8_dialog_content = "Nikinis! ¡Lo hiciste!",
  ui_story_5087_50871602_9_dialog_content = "Si no hubieras detenido el espejo mágico a tiempo, ¡PlayerName y yo no habríamos salido vivos! ¡Nos salvaste!",
  ui_story_5087_50871602_10_dialog_content = "... ¡Eso fue aterrador! No creo que pueda soportar la vista de la nieve otra vez...",
  ui_story_5087_50871602_11_dialog_content = "¡No digas eso! Vas a cansarte de la vista de la nieve en Northland.",
  ui_story_5087_50871602_12_dialog_content = "Nikinis, lo siento por hacerte enfrentar todo por tu cuenta...",
  ui_story_5087_50871602_13_dialog_content = "Estoy bien, Su Majestad. Y... PlayerName—",
  ui_story_5087_50871602_14_dialog_content = "Gracias.",
  ui_story_5087_50871602_15_dialog_content = "... No pareces que necesites más convencimiento.",
  ui_story_5087_50871602_16_dialog_content = "¡Te veré del otro lado!",
  ui_story_5087_50871602_17_dialog_content = "¡Oye! ¡E-Espera un minuto! ¡Shaya! ¿Qué estás haciendo... Ahhhhh! ¿Vamos a saltar? Necesito más tiempo para prepararme para esto—",
  ui_story_5087_50871602_18_dialog_content = "<color=#e8d9bb>¡Chapoteo! Las ondas surgen a través del lago, pero pronto vuelve a estar tranquilo.</color>",
  ui_story_5087_50871602_19_dialog_content = "<color=#e8d9bb>El aroma de las flores flota alrededor de Nikinis. Una vez más, se queda sola entre las flores en el campo.</color>",
  ui_story_5087_50871602_20_dialog_content = "Népolis...",
  ui_story_5087_50871602_21_dialog_content = "Es hora de partir hacia el mundo por el que luchaste tan duro por mí... el mundo sin ti.",
  ui_story_5087_50871602_22_dialog_content = "Debo vivir bien incluso si tú no estás allí... ¿Verdad?",
  ui_story_5087_50871602_23_dialog_content = "<color=#e8d9bb>Nikinis se acerca gradualmente al Lago Espejo. Si solo pudiera quedarse junto al lago un poco más, solo un poco más.</color>",
  ui_story_5087_50871602_24_dialog_content = "<color=#e8d9bb>Lamentablemente, solo le toma unos pocos pasos llegar al borde. Nikinis mira hacia abajo mientras el agua del lago moja los dobladillos de su vestido—</color>",
  ui_story_5087_50871602_25_dialog_content = "¿N-Nepolis?",
  ui_story_5087_50871602_26_dialog_content = "<color=#e8d9bb>Las figuras de Nikinis y Nepolis se reflejan en la superficie del lago.</color>",
  ui_story_5087_50871602_27_dialog_content = "<color=#e8d9bb>Los gemelos bailan junto al lago, acompañados por motas de blanco puro que revolotean con el viento, una danza de nieve a la deriva y pétalos cayendo.</color>",
  ui_story_5087_50871602_28_dialog_content = "<color=#e8d9bb>¡Bailar! ¡Baila eternamente hasta el fin de los tiempos!</color>",
  ui_story_5087_50871602_29_dialog_content = "<color=#e8d9bb>Este sería un final verdaderamente maravilloso para la historia, un hermoso poema conocido solo por el viento y la nieve.</color>",
  ui_story_5087_50871602_30_dialog_content = "Mi hermana... Estaré allí cuando me necesites...",
  ui_story_5087_50871602_31_dialog_content = "<color=#e8d9bb>¡Chapoteo! Las ondas surgen a través del lago una vez más.</color>",
  ui_story_5087_50871602_32_dialog_content = "<color=#e8d9bb>Aún permanece la hermosa y poética reflexión.</color>",
  ui_story_5087_50871602_33_dialog_content = "<color=#e8d9bb>Permanece rodeado de nieve, brillando dentro del espejo...</color>"
}
return config
